\label{prop:discrete-perturbation-estimate}
    For every $\lambda\in[0,1)$, $\theta\in\Theta$, and $t \in {\cal T}$,
    \begin{align}
        d_{\mathrm{TV}}(M_t^{\lambda,\theta}(\omega),\mu_t^\theta)\leq\lambda,
        \qquad\mathbb{P}(\mathrm{d} \omega)\text{-a.s.}
    \end{align}

\label{theorem:discrete-perturbation-consistency}
    Under Assumption~\ref{assumption:discrete-uniform-regularity}, there exists $C_T>0$, independent of $\theta$ and $\lambda$, such that, for $\lambda\in[0,1)$,
    \begin{align}
        \sup_{\theta\in\Theta}|J^\lambda(\theta)-J(\theta)|\leq C_T\lambda.
    \end{align}
    Moreover, under Assumption~\ref{assumption:discrete-gradient-regularity}, there exists $C_T^\nabla > 0$ such that
    \begin{align}
        \sup_{\theta\in\Theta}\|\nabla_\theta J^\lambda(\theta)-\nabla_\theta J(\theta)\|
        \leq C_T^\nabla\lambda.
    \end{align}

\label{corollary:discrete-maximizers}
    Under Assumptions~\ref{assumption:discrete-uniform-regularity} and~\ref{assumption:discrete-gradient-regularity}, suppose that $\Theta$ is compact. Then, for every $\lambda\in[0,1)$, $J^\lambda$ attains its maximum on $\Theta$ at some $\theta_\lambda^\star$, and
    \begin{align}
        J(\theta_\lambda^\star)\geq\max_{\theta\in\Theta}J(\theta)-2C_T\lambda.
    \end{align}
    Moreover, every accumulation point of $(\theta_\lambda^\star)$ as $\lambda\to0$ maximizes $J$.

\label{theorem:discrete-pg-representation}
    Under Assumptions ~\ref{assumption:discrete-uniform-regularity},
    ~\ref{assumption:discrete-gradient-regularity} and~\ref{assumption:randomizer_rho_discrete}, for every $\lambda\in(0,1)$, and using the quantities defined in~\eqref{eq:perturbed-objective} and~\eqref{eq:discrete-main-scores},
    \begin{align}
        \nabla_\theta J^\lambda(\theta) = \mathbb{E}\big[{\cal R}_\theta^\lambda ({\cal S}_{\mathrm{pol}}^{\lambda,\theta}+{\cal S}_{\mathrm{mf}}^{\lambda,\theta})\big].
    \end{align}

\label{theorem:discrete-bias-mse}
    Under Assumptions~\ref{assumption:discrete-uniform-regularity}, \ref{assumption:discrete-gradient-regularity}, \ref{assumption:randomizer_rho_discrete}, and~\ref{assumption:discrete-score-regularity}, if $0<\lambda,\eta<1$, integers $B,M,n\geq1$, and $n\eta^2\geq1$, there exists $C>0$, independent of $\theta,\lambda,\eta,B,M,n$, such that
    \begin{align}
        \|\mathbb{E}[\widehat G_{B,M,n}^{\lambda,\eta}(\theta)]-\nabla_\theta J(\theta)\|
        &\leq C\bigg(\lambda+\eta+\frac1{\eta\sqrt n}+\frac1{\sqrt M}\bigg),\\
        \mathbb{E} \Big[\|\widehat G_{B,M,n}^{\lambda,\eta}(\theta)-\nabla_\theta J(\theta)\|^2 \Big]
        &\leq C\bigg(\lambda^2+\frac{1+\lambda^{-2}}B+\eta^2+\frac1{n\eta^2}+\frac1M\bigg).
    \end{align}

\label{prop:continuous-state-transport}
For every $\lambda\in[0,1)$, the construction in Appendix~\ref{app:continuous-construction} gives a jointly measurable map $T_{K,t}^{\lambda,\theta}: \Omega \times \mathbb{R}^d \times [0,1] \to \mathbb{R}^d$ such that
\begin{align}
 M_{K,t}^{\lambda,\theta}(\omega)&=T_{K,t}^{\lambda,\theta}(\omega,\cdot,\cdot)\sharp(\nu_{K,t}^\theta\otimes{\cal U}([0,1]))\\
 &= \sum_{j=1}^K p_{j,K,t}^{\lambda,\theta}(\omega)\,{\cal N}\Big(m_{j,K,t}^{\lambda,\theta}(\omega),\Sigma_{j,K,t}^{\lambda,\theta}(\omega)\Big).
\end{align}

\label{proposition:continuous-perturbation-estimate}
    Under Assumption~\ref{assumption:continuous-moment-bounds}, there exists $C_K>0$, uniform in $t$, $\theta$, and $\lambda\in[0,1)$, such that
    \begin{align}
        \big(\mathbb{E}[{\cal W}_2^2(M_{K,t}^{\lambda,\theta},\mu_t^\theta)]\big)^{1/2}
        \leq{\cal W}_2(\nu_{K,t}^\theta,\mu_t^\theta)+C_K \sqrt{\lambda}.
    \end{align}

\label{theorem:continuous-objective-perturbation-consistency}
    Under Assumptions~\ref{assumption:continuous-moment-bounds} and~\ref{assumption:continuous-objective-regularity}, there exists $C_{K,T}>0$, independent of $\theta$ and $\lambda$, such that
    \begin{align}
        \sup_{\theta\in\Theta}|J_K^\lambda(\theta)-J_K(\theta)|\leq C_{K,T}\sqrt\lambda,
        \qquad\lambda\in[0,1).
    \end{align}

\label{prop:continuous-optimality-gap}
    Under Assumptions~\ref{assumption:continuous-moment-bounds} and~\ref{assumption:continuous-objective-regularity}, let $\theta^{\star}_{K,\lambda}\in\Theta$ be a maximizer of $J_K^\lambda$ over $\Theta$. Then
    \begin{align}
        0\leq\sup_{\theta\in\Theta}J(\theta)-J(\theta^{\star}_{K,\lambda})
        \leq2\big(C_T^{\mathrm{proj}}\varepsilon_K+C_{K,T}\sqrt\lambda\big).
    \end{align}

\label{theorem:continuous-gradient-convergence}
    Under the preceding Assumptions and Assumption~\ref{assumption:continuous-gradient-regularity}, $J_K^\lambda$ and $J_K$ are differentiable, there exists $C_{K,T}^\nabla < \infty$, independent of $\theta$ and $\lambda$, and there exists $\lambda_0 \in (0,1)$, such that, for $\lambda\in[0,\lambda_0]$,
    \begin{align}
        \sup_{\theta\in\Theta} \|\nabla_\theta J_K^\lambda(\theta) - \nabla_\theta J_K(\theta)\| \leq C_{K,T}^\nabla \lambda.
    \end{align}

\label{lemma:continuous-main-density}
Under conditions (1)--(2) of Assumption~\ref{assumption: randomizer_rho}, the random variable $\Psi_\lambda(z,R_t)$ admits a density $h^\lambda(\cdot\mid z):\widetilde{\cal Z}_K\to[0,\infty)$. For $y\in Y_\lambda(z)$, write $(q,a,b)=(q^\lambda,a^\lambda,b^\lambda)(y\mid z)$. Then
\begin{align}
    h^\lambda(y\mid z)
    =\frac{f_Q(q)\,f_A(a)\,f_B(b)}{\mathcal J^\lambda(z,b)},
    \label{eq:continuous-main-density}
\end{align}
where $\mathcal J^\lambda:\widetilde{\cal Z}_K\times({\cal B}_\lambda)^K\to(0,\infty)$ is the Jacobian factor given in~\eqref{eq:continuous-explicit-jacobian}. The density is zero outside $Y_\lambda(z)$.

\label{theorem:continuous-pg-representation}
 Let $\lambda\in(0,1)$. Under Assumptions~\ref{assumption: randomizer_rho} and~\ref{assumption:continuous-likelihood-ratio-regularity}, the following holds:
 \begin{align}
  \nabla_\theta J_K^\lambda(\theta)=\mathbb{E}[{\cal R}_K^{\lambda,\theta}({\cal S}_{\mathrm{pol}}+{\cal S}_{\mathrm{mf}})].
 \end{align}

\label{theorem:continuous-bias-mse}
    Under Assumptions~\ref{assumption:continuous-moment-bounds}, \ref{assumption:continuous-objective-regularity}, \ref{assumption:continuous-gradient-regularity}, \ref{assumption: randomizer_rho}, \ref{assumption:continuous-likelihood-ratio-regularity}, and~\ref{assumption:continuous-statistical-regularity}, let $n_0 = n/(2d_\theta)$. For admissible scales $0<\lambda\leq\lambda_0$, $0<\eta\leq\eta_0$, with $a_{n_0} \leq \eta$, there exists $C<\infty$, independent of $\theta,\lambda,\eta,B,M,n_0$ such that 
    \begin{align}
        \Big\|\mathbb{E}\big[\widehat G^{\lambda,\eta}_{B,M,n}(\theta)\big]-\nabla_\theta J_K(\theta)\Big\|
        &\leq C\bigg(\lambda + a_M + \eta^2 + \frac{a_{n_0}}{\eta}  \bigg),\\
        \mathbb{E} \Big[\big\|\widehat G^{\lambda,\eta}_{B,M,n}(\theta)-\nabla_\theta J_K(\theta)\big\|^2 \Big]
        &\leq C\bigg( \lambda^2 + a_M^2 + \eta^4 + \frac{a_{n_0}^2}{\eta^2} + \frac{1+\lambda^{-2}}{B} \bigg).
    \end{align}

Starting from $\mu_0$, compute successively
\begin{align}
    \mu_{t+1}^\theta(j)=\sum_{i=1}^N\mu_t^\theta(i)K_t^\theta(x_j\mid x_i,\mu_t^\theta),
    \qquad j\in\llbracket1,N\rrbracket.
    \label{eq:discrete-well-posedness-flow}
\end{align}
Each right-hand side is nonnegative, and summing over $j$ gives one. This recursion therefore determines a unique flow in $\Delta_N$. Substituting that flow into the policy and transition kernels determines the joint law of states and actions by the canonical construction. To check continuity, let $\theta_n\to\theta$. The claim is immediate at $t=0$, since $\mu_0^{\theta_n}=\mu_0^\theta=\mu_0$. Suppose that $\mu_t^{\theta_n}(i)\to\mu_t^\theta(i)$ for every $i$. By the continuity of $K_t^\theta$ and the fact that the sum is finite, for every $j$,
\begin{align}
    \mu_{t+1}^{\theta_n}(j)
    &=\sum_{i=1}^N\mu_t^{\theta_n}(i)K_t^{\theta_n}(x_j\mid x_i,\mu_t^{\theta_n})
    \longrightarrow
    \sum_{i=1}^N\mu_t^\theta(i)K_t^\theta(x_j\mid x_i,\mu_t^\theta)
    =\mu_{t+1}^\theta(j).
\end{align}
Thus induction gives continuity of $\theta\mapsto\mu_t^\theta$ for every $t$. Consequently,
\begin{align}
    J(\theta)=\sum_{t=0}^{T-1}\sum_{i=1}^N\mu_t^\theta(i)R_t^\theta(x_i,\mu_t^\theta)
    +\sum_{i=1}^N\mu_T^\theta(i)g(x_i,\mu_T^\theta)
\end{align}
is continuous and has the stated bound.

For the perturbed process, fix a realization $q=(q_1,\ldots,q_T)\in(\Delta_N)^T$ of the randomizers and write
\begin{align}
    M_0^{\lambda,\theta}(q)&\coloneqq\mu_0, &
    M_t^{\lambda,\theta}(q)&\coloneqq(1-\lambda)\mu_t^\theta+\lambda q_t,\quad t\geq1.
\end{align}
These supplied population arguments are continuous in $\theta$ by the result just proved. Conditional on $q$, define the state-law recursion
\begin{align}
\begin{cases}
    \widetilde\mu_0^{\lambda,\theta,q}&\coloneqq\mu_0,\\
    \widetilde\mu_{t+1}^{\lambda,\theta,q}(j)
    &\coloneqq\sum_{i=1}^N\widetilde\mu_t^{\lambda,\theta,q}(i)
    K_t^\theta\big(x_j\mid x_i,M_t^{\lambda,\theta}(q)\big).
\end{cases}
\end{align}
The same induction as above, now using continuity of both $\theta\mapsto M_t^{\lambda,\theta}(q)$ and $(\theta,m)\mapsto K_t^\theta(\cdot\mid x_i,m)$, shows that $\widetilde\mu_t^{\lambda,\theta_n,q}\to\widetilde\mu_t^{\lambda,\theta,q}$ for every $t$. Hence the conditional objective
\begin{align}
    \mathcal J^\lambda(\theta,q)
    \coloneqq\sum_{t=0}^{T-1}\sum_{i=1}^N\widetilde\mu_t^{\lambda,\theta,q}(i)
    R_t^\theta\big(x_i,M_t^{\lambda,\theta}(q)\big) +\sum_{i=1}^N\widetilde\mu_T^{\lambda,\theta,q}(i) g\big(x_i,M_T^{\lambda,\theta}(q)\big)
\end{align}
is continuous in $\theta$. Moreover, $|\mathcal J^\lambda(\theta,q)|\leq T\overline r+\overline g$ for every $(\theta,q)$. Since $J^\lambda(\theta)=\mathbb E_q[\mathcal J^\lambda(\theta,q)]$ and the law of $q$ is independent of $\theta$, dominated convergence gives continuity of $J^\lambda$. The final claim follows from compactness.

\label{assumption:well-posedness}
    The parameter set $\Theta \subset \mathbb{R}^{d_\theta}$ is non-empty, and the initial law $\mu_0 \in {\cal P}_2({\cal X})$ is independent of $\theta$. For each $t \in \llbracket0,T-1\rrbracket$, the following conditions hold.
    \begin{enumerate}
        \item \emph{Continuity of the kernels.} For every sequence $(\theta_n,x_n,m_n,a_n) \to (\theta,x,m,a)$ in $\Theta\times {\cal X}\times{\cal P}_2({\cal X}) \times {\cal A}$,
        \begin{align}
            {\cal W}_2\big(\pi_t^{\theta_n}(\cdot\mid x_n,m_n), \pi_t^\theta(\cdot\mid x,m)\big) \longrightarrow 0,\qquad
            {\cal W}_2\big(P_t(\cdot\mid x_n,m_n,a_n), P_t(\cdot\mid x,m,a)\big) \longrightarrow0.
        \end{align}
        \item \emph{Continuity of the rewards.} The maps $r_t : {\cal X}\times {\cal P}_2({\cal X}) \times {\cal A} \to \mathbb{R}$ and $g:{\cal X}\times{\cal P}_2({\cal X}) \to \mathbb{R}$ are jointly continuous. 
        \item \emph{Quadratic growth.} There exists $C\geq 0$ such that, for all $(\theta,x,m,a) \in \Theta\times{\cal X}\times{\cal P}_2({\cal X})\times{\cal A}$,
        \begin{align}
            \int_{\cal A} \|b\|^2 \pi_t^\theta(\mathrm{d} b\mid x,m) &\leq C\big(1+\|x\|^2 + M_2(m)\big),\\
            \int_{\cal X} \|y\|^2 P_t(\mathrm{d} y\mid x,m,a) &\leq C\big(1+\|x\|^2 + \|a\|^2 + M_2(m)\big),\\
            |r_t(x,m,a)| &\leq C\big(1+\|x\|^2 + \|a\|^2 + M_2(m)\big),\\
            |g(x,m)| &\leq C\big(1+\|x\|^2+M_2(m)\big).
        \end{align}
    \end{enumerate}

Under Assumption~\ref{assumption:well-posedness}, $\mu_t^\theta \in {\cal P}_2({\cal X})$ for all $(\theta,t) \in \Theta\times{\cal T}$, and
    \begin{align}
        \sup_{\theta\in\Theta}\big(\max_{t\in{\cal T}} \mathbb{E}\big[\|X_t^\theta\|^2\big] + \max_{t\in\llbracket0,T-1\rrbracket} \mathbb{E}\big[\|\alpha_t^\theta\|^2 \big]\big) < \infty.
    \end{align}
    Moreover, for every $t\in{\cal T}$, the map $\theta\mapsto\mu_t^\theta$ is continuous from $\Theta$ to $({\cal P}_2({\cal X}), {\cal W}_2)$, and the objective $J : \Theta\to\mathbb{R}$ is finite, bounded and continuous on $\Theta$.

Fix $\theta\in\Theta$. The canonical construction yields, for $t\in\llbracket0,T-1\rrbracket$ and $B\in{\cal B}({\cal X})$,
    \begin{align}
        \label{eq:well-posedness-probability-flow}
        \mu_{t+1}^\theta(B) = \int_{\cal X} \int_{\cal A} P_t(B\mid x,\mu_t^\theta,a)\pi_t^\theta(\mathrm{d} a\mid x,\mu_t^\theta)\mu_t^\theta(\mathrm{d} x).
    \end{align}
    Starting from $\mu_0^\theta = \mu_0$, equation~\eqref{eq:well-posedness-probability-flow} determines the probability flow $(\mu_t^\theta)_{t\in{\cal T}}$.

    The joint law of the states and actions is then
    \begin{align}
        \mu_0(\mathrm{d} x_0) \prod_{t=0}^{T-1} \big[\pi_t^\theta(\mathrm{d} a_t\mid x_t,\mu_t^\theta) P_t(\mathrm{d} x_{t+1}\mid x_t,\mu_t^\theta, a_t) \big].
    \end{align}

    We prove by induction that each $\mu_t^\theta$ has finite second moment. Whenever $\mu_t^\theta\in{\cal P}_2({\cal X})$, write $u_t^\theta\coloneqq M_2(\mu_t^\theta)$. Assumption~\ref{assumption:well-posedness} gives
    \begin{align}
        \mathbb{E}\big[\|\alpha_t^\theta\|^2 \big] \leq C(1+2u_t^\theta),\qquad
        u_{t+1}^\theta \leq C\big(1+2u_t^\theta+C(1+2u_t^\theta)\big).
    \end{align}
    Thus $\mu_{t+1}^\theta \in {\cal P}_2({\cal X})$ and the second inequality bounds $u_{t+1}^\theta$. Since $u_0^\theta = M_2(\mu_0)$ is independent of $\theta$, $C$ is uniform in $t$ and $\theta$, and $T$ is finite, induction gives the uniform second-moment bounds. Moreover,
    \begin{align}
        \mathbb{E}\big[\big|r_t(X_t^\theta, \mu_t^\theta,\alpha_t^\theta)\big| \big] \leq C\big(1 + 2u_t^\theta + \mathbb{E}\big[\|\alpha_t^\theta\|^2 \big]\big)<\infty,\qquad
        \mathbb{E}\big[\big|g(X_T^\theta,\mu_T^\theta)\big|\big] \leq C\big(1 + 2u_T^\theta\big) < \infty.
    \end{align}
    Hence $J(\theta)$ is finite and the uniform bound over $\theta\in\Theta$ follows from the uniform constant $C$.

    To prove continuity, let $\theta_n \to \theta$ in $\Theta$. We prove $\mu_t^{\theta_n} \to \mu_t^\theta$ in ${\cal W}_2$ by induction on $t$. The case $t=0$ is immediate because all initial laws equal $\mu_0$. Suppose the claim holds at some $t<T$.

    We use the characterization of convergence in the Wasserstein space in \citet[Definition~6.6 and Theorem~6.7]{villani2009optimal}. Fix a continuous function $f : {\cal X} \to \mathbb{R}$ satisfying $|f(y)|\leq C_f(1+\|y\|^2)$ for some $C_f<\infty$. Applying this characterization successively to $P_t$ and $\pi_t^\theta$, together with their continuity and quadratic-growth bounds, shows that the map
    \begin{align}
        \Theta \times {\cal X} \times {\cal P}_2({\cal X}) \ni (\theta,x,m) \longmapsto h(\theta,x,m) \coloneqq \int_{\cal A} \int_{\cal X} f(y) P_t(\mathrm{d} y\mid x,m,a) \pi_t^\theta(\mathrm{d} a\mid x,m) \in \mathbb{R}
    \end{align}
    is continuous and satisfies
    \begin{align}
        \label{eq:well-posedness-growth-h}
        |h(\theta,x,m)| \leq C_f\Big(1 + C(1+C)\big(1+\|x\|^2 + M_2(m)\big)\Big). 
    \end{align}
    Passage to the limit follows by uniform convergence on compact sets and uniform integrability. Indeed, by~\eqref{eq:well-posedness-probability-flow},
    \begin{align}
        \int_{\cal X} f\mathrm{d}\mu_{t+1}^{\theta_n} - \int_{\cal X} f\mathrm{d}\mu_{t+1}^\theta = \int_{\cal X}\big(h(\theta_n, x,\mu_t^{\theta_n}) - h(\theta,x,\mu_t^\theta)\big) \mu_t^{\theta_n}(\mathrm{d} x) + \bigg(\int_{\cal X} h(\theta,x,\mu_t^\theta)\mu_t^{\theta_n}(\mathrm{d} x) - \int_{\cal X} h(\theta,x,\mu_t^\theta) \mu_t^\theta(\mathrm{d} x)\bigg).
    \end{align}
    The second term vanishes by the induction hypothesis and the characterization, since $h(\theta,\cdot,\mu_t^\theta)$ is continuous with quadratic growth by~\eqref{eq:well-posedness-growth-h}. For the first term, fix $R>0$. On the compact set ${\cal X}\cap\{\|x\|\leq R\}$, $h(\theta_n,\cdot,\mu_t^{\theta_n})\to h(\theta,\cdot,\mu_t^\theta)$ uniformly, because $h$ is uniformly continuous on the compact set $(\{\theta_n\}_n\cup\{\theta\})\times({\cal X}\cap\{\|x\|\leq R\})\times(\{\mu_t^{\theta_n}\}_n\cup\{\mu_t^\theta\})$. On $\{\|x\|>R\}$, the bound~\eqref{eq:well-posedness-growth-h} and $\sup_nM_2(\mu_t^{\theta_n})<\infty$ give $|h(\theta_n,x,\mu_t^{\theta_n})-h(\theta,x,\mu_t^\theta)|\le K(1+\|x\|^2)$ for some $K$ independent of $n$. Hence
    \begin{align}
        \limsup_{n\to\infty} \bigg|\int_{\cal X} \big(h(\theta_n,x,\mu_t^{\theta_n})-h(\theta,x,\mu_t^\theta)\big) \mu_t^{\theta_n}(\mathrm{d} x)\bigg|
        \leq K \limsup_{n\to\infty} \int_{\{\|x\|>R\}}(1 + \|x\|^2) \mu_t^{\theta_n}(\mathrm{d} x),
    \end{align}
    and the right-hand side vanishes as $R\to\infty$ by the uniform integrability part of the characterization. Therefore $\int f\,\mathrm{d}\mu_{t+1}^{\theta_n}\to\int f\,\mathrm{d}\mu_{t+1}^\theta$. Since $f$ is arbitrary, the characterization yields $\mu_{t+1}^{\theta_n}\to\mu_{t+1}^\theta$ in ${\cal W}_2$, which completes the induction.

    Finally, for $t\in\llbracket0,T-1\rrbracket$,
    \begin{align}
        \mathbb{E}\big[r_t(X_t^\theta,\mu_t^\theta,\alpha_t^\theta)\big]=\int_{\cal X}\int_{\cal A} r_t(x,\mu_t^\theta,a)\,\pi_t^\theta(\mathrm{d} a\mid x,\mu_t^\theta)\,\mu_t^\theta(\mathrm{d} x).
    \end{align}
    Since $r_t$ is continuous with quadratic growth by Assumption~\ref{assumption:well-posedness}, the argument above, with $r_t(x,m,a)$ in place of $\int_{\cal X} f(y)P_t(\mathrm{d} y\mid x,m,a)$, shows that $(\theta,x,m)\mapsto\int_{\cal A} r_t(x,m,a)\,\pi_t^\theta(\mathrm{d} a\mid x,m)$ is continuous and bounded by $C(1+C)(1+\|x\|^2+M_2(m))$. The same splitting then gives $\mathbb{E}[r_t(X_t^{\theta_n},\mu_t^{\theta_n},\alpha_t^{\theta_n})]\to\mathbb{E}[r_t(X_t^\theta,\mu_t^\theta,\alpha_t^\theta)]$. The terminal term is handled identically with $g(\cdot,\mu_T^{\theta_n})$ in place of $h(\theta_n,\cdot,\mu_t^{\theta_n})$. Hence $J(\theta_n)\to J(\theta)$, and $J$ is continuous on $\Theta$.

At $t=0$, the distance is zero because $M_0^{\lambda,\theta} = \mu_0$. For $t\geq1$, since $M_t^{\lambda,\theta}(\omega)=(1-\lambda)\mu_t^\theta+\lambda Q_t(\omega)$ for any $\omega \in \Omega$, and $d_\mathrm{TV}(\mu,\nu) \leq 1$ for any $\mu,\nu\in{\cal P}({\cal X})$, it follows that 
    \begin{align}
        d_{\mathrm{TV}}(M_t^{\lambda,\theta}(\omega),\mu_t^\theta)
        =\lambda d_{\mathrm{TV}}(Q_t(\omega),\mu_t^\theta)\leq\lambda, \text{ for any $\omega \in \Omega$.}
    \end{align}

\label{assumption:discrete-uniform-regularity}
The maps $r_t$ and $g$ are uniformly bounded in all their arguments by $\overline R$ and $\overline g$, respectively. For all admissible $t,\theta,i,m,m'$, we assume that the following bounds hold with constants independent of these arguments:
    \begin{align}
    \begin{cases}
d_{\mathrm{TV}}\bigl(K_t^\theta(\cdot\mid i,m),K_t^\theta(\cdot\mid i,m')\bigr)
        &\leq L_K d_{\mathrm{TV}}(m,m'),\nonumber\\
        |R_t^\theta(i,m)-R_t^\theta(i,m')|&\leq L_R d_{\mathrm{TV}}(m,m'),\nonumber\\
        |g(i,m)-g(i,m')|&\leq L_g d_{\mathrm{TV}}(m,m').
    \end{cases}
    \end{align}

\label{lemma:discrete-stability-state-marginal}
    Under Assumption~\ref{assumption:discrete-uniform-regularity}, the law $\nu_t^{\lambda,\theta}={\cal L}(X_t^{\lambda,\theta})$ satisfies
    \begin{align}
        d_{\mathrm{TV}}(\nu_t^{\lambda,\theta},\mu_t^\theta)\leq L_Kt\lambda,
        \qquad t \in \llbracket 1,T \rrbracket.
    \end{align}

For $t\in\llbracket0,T-1\rrbracket$, define the averaged kernel $\overline K_t^{\lambda,\theta} : {\cal X} \to {\cal P}({\cal X})$ by
    $\overline K_t^{\lambda,\theta}(\cdot\mid x) \coloneqq \mathbb{E}[K_t^\theta(\cdot\mid x,M_t^{\lambda,\theta})]$. By definition of $K_t^\theta$, conditionally on $(X_t^{\lambda,\theta}, M_t^{\lambda,\theta}) = (x,m)$, the next state has law $K_t^\theta(\cdot\mid x,m)$. For $t\geq1$, $X_t^{\lambda,\theta}$ depends on the perturbation randomizers only through $U_1,\ldots,U_{t-1}$, whereas $M_t^{\lambda,\theta}$ depends on the randomizer $U_t$. Hence $X_t^{\lambda,\theta}$ and $M_t^{\lambda,\theta}$ are independent. At $t=0$, $M_0^{\lambda,\theta}=\mu_0$ is deterministic. Therefore,
    \begin{align}
        {\cal L}\big(X_{t+1}^{\lambda,\theta} \mid X_t^{\lambda,\theta}=x\big) = \overline K_t^{\lambda,\theta}(\cdot\mid x).
    \end{align}
    It follows that $\nu_{t+1}^{\lambda,\theta} = \nu_t^{\lambda,\theta} \overline K_t^{\lambda,\theta}$. On the other hand, the unperturbed population flow satisfies
    \begin{align}
        \label{eq:population-recursion}
        \mu_{t+1}^\theta = \mu_t^\theta K_t^\theta(\cdot\mid \cdot,\mu_t^\theta).
    \end{align}

    For a probability measure $\nu$ and a Markov kernel $K$, we use the notation $(\nu K)(i):=\sum_{j=1}^N K(i\mid j)\nu(j)$. We bound $d_{\mathrm{TV}}(\nu_{t+1}^{\lambda,\theta},\mu_{t+1}^\theta)$ by inserting the intermediate law $\nu_t^{\lambda,\theta}K_t^\theta(\cdot\mid\cdot,\mu_t^\theta)$. By the triangle inequality,
    \begin{align}
        d_{\mathrm{TV}}(\nu_{t+1}^{\lambda,\theta},\mu_{t+1}^\theta)
        &\leq \underbrace{d_{\mathrm{TV}}\big(\nu_t^{\lambda,\theta}\overline K_t^{\lambda,\theta},\,\nu_t^{\lambda,\theta}K_t^\theta(\cdot\mid\cdot,\mu_t^\theta)\big)}_{(\mathrm{I})}
        +\underbrace{d_{\mathrm{TV}}\big(\nu_t^{\lambda,\theta}K_t^\theta(\cdot\mid\cdot,\mu_t^\theta),\,\mu_t^\theta K_t^\theta(\cdot\mid\cdot,\mu_t^\theta)\big)}_{(\mathrm{II})}.
        \label{eq:discrete-stability-split}
    \end{align}

    \emph{Bounding $(\mathrm{I})$:} Fix $j\in\llbracket 1,N\rrbracket$. Since $\overline K_t^{\lambda,\theta}(\cdot\mid j)=\mathbb{E}[K_t^\theta(\cdot\mid j,M_t^{\lambda,\theta})]$ and $\mu\mapsto d_{\mathrm{TV}}(\mu,\nu)=\sup_A|\mu(A)-\nu(A)|$ is a supremum of functionals affine in $\mu$ (hence convex), Jensen's inequality gives
    \begin{align}
        d_{\mathrm{TV}}\big(\overline K_t^{\lambda,\theta}(\cdot\mid j),\,K_t^\theta(\cdot\mid j,\mu_t^\theta)\big)
        &=d_{\mathrm{TV}}\Big(\mathbb{E}\big[K_t^\theta(\cdot\mid j,M_t^{\lambda,\theta})\big],\,K_t^\theta(\cdot\mid j,\mu_t^\theta)\Big)\nonumber\\
        &\leq \mathbb{E}\Big[d_{\mathrm{TV}}\big(K_t^\theta(\cdot\mid j,M_t^{\lambda,\theta}),\,K_t^\theta(\cdot\mid j,\mu_t^\theta)\big)\Big]\nonumber\\
        &\leq L_K\,\mathbb{E}\big[d_{\mathrm{TV}}(M_t^{\lambda,\theta},\mu_t^\theta)\big]
        \;\leq\;L_K\lambda,
        \label{eq:discrete-kernel-rows-close}
    \end{align}
    using Assumption~\ref{assumption:discrete-uniform-regularity} in the second-to-last step and the perturbation estimate of Proposition~\ref{prop:discrete-perturbation-estimate} in the last step. Since $\nu_t^{\lambda,\theta}$ is a probability measure on $\llbracket 1,N\rrbracket$, for any $A$
    \begin{align}
        \big|\nu_t^{\lambda,\theta}\overline K_t^{\lambda,\theta}(A)-\nu_t^{\lambda,\theta}K_t^\theta(\cdot\mid\cdot,\mu_t^\theta)(A)\big|
        &=\Big|\sum_{j=1}^N\nu_t^{\lambda,\theta}(j)\big(\overline K_t^{\lambda,\theta}(A\mid j)-K_t^\theta(A\mid j,\mu_t^\theta)\big)\Big|\nonumber\\
        &\leq\sum_{j=1}^N\nu_t^{\lambda,\theta}(j)\,d_{\mathrm{TV}}\big(\overline K_t^{\lambda,\theta}(\cdot\mid j),K_t^\theta(\cdot\mid j,\mu_t^\theta)\big)
        \;\leq\;L_K\lambda,
    \end{align}
    and taking the supremum over $A$ yields $(\mathrm{I})\leq L_K\lambda$.

    \emph{Bounding $(\mathrm{II})$:} Here the same kernel row $K_t^\theta(\cdot\mid\cdot,\mu_t^\theta)$ is applied to the two laws $\nu_t^{\lambda,\theta}$ and $\mu_t^\theta$, so it suffices to show the general contraction property
    \begin{align}
        d_{\mathrm{TV}}(\nu K,\mu K)\leq d_{\mathrm{TV}}(\nu,\mu)
        \label{eq:markov-kernel-contraction}
    \end{align}
    for any probability measures $\nu,\mu$ on $\llbracket 1,N\rrbracket$ and any Markov kernel $K$ on $\llbracket 1,N\rrbracket$. Let $A^\star=\{j:\nu(j)>\mu(j)\}$; since $\sum_j(\nu(j)-\mu(j))=0$, the standard identity \citep[Proposition~4.2 and Remark~4.3]{levin2026markov} $d_{\mathrm{TV}}(\nu,\mu)=\nu(A^\star)-\mu(A^\star)=\sum_{j\in A^\star}(\nu(j)-\mu(j))=-\sum_{j\notin A^\star}(\nu(j)-\mu(j))$ holds. Then, for any $A$,
    \begin{align}
        (\nu K)(A)-(\mu K)(A)
        &=\sum_{j=1}^N\big(\nu(j)-\mu(j)\big)K(A\mid j)\nonumber\\
        &=\sum_{j\in A^\star}\big(\nu(j)-\mu(j)\big)K(A\mid j)+\sum_{j\notin A^\star}\big(\nu(j)-\mu(j)\big)K(A\mid j)\nonumber\\
        &\leq\sum_{j\in A^\star}\big(\nu(j)-\mu(j)\big)\cdot 1+\sum_{j\notin A^\star}\big(\nu(j)-\mu(j)\big)\cdot 0
        =d_{\mathrm{TV}}(\nu,\mu),
    \end{align}
    where the inequality uses $K(A\mid j)\leq 1$ on $A^\star$ (where $\nu(j)-\mu(j)\geq0$) and $K(A\mid j)\geq 0$ off $A^\star$ (where $\nu(j)-\mu(j)\leq 0$). Applying the same argument to $(\mu K)(A)-(\nu K)(A)$ gives the reverse bound, so $|(\nu K)(A)-(\mu K)(A)|\leq d_{\mathrm{TV}}(\nu,\mu)$ for every $A$, and \eqref{eq:markov-kernel-contraction} follows by taking the supremum over $A$. Applying \eqref{eq:markov-kernel-contraction} with $K=K_t^\theta(\cdot\mid\cdot,\mu_t^\theta)$ gives $(\mathrm{II})\leq d_{\mathrm{TV}}(\nu_t^{\lambda,\theta},\mu_t^\theta)$.
    Consequently, combining the bounds on $(\mathrm{I})$ and $(\mathrm{II})$ in \eqref{eq:discrete-stability-split},
    \begin{align}
        d_{\mathrm{TV}}(\nu_{t+1}^{\lambda,\theta},\mu_{t+1}^\theta)
        \leq d_{\mathrm{TV}}(\nu_t^{\lambda,\theta},\mu_t^\theta)+L_K\lambda.
    \end{align}
    The result follows by induction from $\nu_0^{\lambda,\theta}=\mu_0$.

Fix $t\in\llbracket 0,T-1\rrbracket$. We add and subtract $\mathbb{E}[R_t^\theta(X_t^{\lambda,\theta},\mu_t^\theta)]$. By the Lipschitz property in Assumption~\ref{assumption:discrete-uniform-regularity} and Proposition~\ref{prop:discrete-perturbation-estimate}, $|R_t^\theta(X_t^{\lambda,\theta},M_t^{\lambda,\theta})-R_t^\theta(X_t^{\lambda,\theta},\mu_t^\theta)|\leq L_R\,d_{\mathrm{TV}}(M_t^{\lambda,\theta},\mu_t^\theta)\leq L_R\lambda$ point-wise. Moreover, since $|R_t^\theta|\leq\overline R$ and $\nu_t^{\lambda,\theta}={\cal L}(X_t^{\lambda,\theta})$,
    \begin{align}
        \Big|\mathbb{E}\big[R_t^\theta(X_t^{\lambda,\theta},\mu_t^\theta)\big]-\sum_i\mu_t^\theta(i)R_t^\theta(i,\mu_t^\theta)\Big|
        =\Big|\sum_i\big(\nu_t^{\lambda,\theta}(i)-\mu_t^\theta(i)\big)R_t^\theta(i,\mu_t^\theta)\Big|
        \leq 2\overline R\,d_{\mathrm{TV}}(\nu_t^{\lambda,\theta},\mu_t^\theta),
    \end{align}
    using $\sum_i|\nu(i)-\mu(i)|=2d_{\mathrm{TV}}(\nu,\mu)$. Hence
    \begin{align}
        \Big|\mathbb{E}\big[R_t^\theta(X_t^{\lambda,\theta},M_t^{\lambda,\theta})\big] - \sum_i\mu_t^\theta(i)R_t^\theta(i,\mu_t^\theta)\Big|
        \leq 2\overline R\,d_{\mathrm{TV}}(\nu_t^{\lambda,\theta},\mu_t^\theta)+L_R\lambda.
    \end{align}
    The terminal contribution is bounded by $2\overline g\,d_{\mathrm{TV}}(\nu_T^{\lambda,\theta},\mu_T^\theta)+L_g\lambda$. Summing and applying the lemma yields
    \begin{align}
        |J^\lambda(\theta)-J(\theta)|\leq C_T\lambda,\qquad
        C_T=\overline R L_KT(T-1)+L_RT+2\overline gL_KT+L_g.
    \end{align}

\label{assumption:discrete-gradient-regularity}
    There is an open set $\Theta^\circ\supset\Theta$ such that the following conditions hold. Derivatives in $m$ are taken in the coordinates $(m_1,\ldots,m_{N-1})$, with $m_N = 1-\sum_{k=1}^{N-1} m_k$.
    \begin{enumerate}
        \item [(1)] For every $t \in \llbracket0,T-1\rrbracket$, $i,j\in\llbracket1,N\rrbracket$ and $\nu_A$-a.e.\ $a \in {\cal A}$, the map $(\theta,m) \mapsto p_t^\theta(a\mid x_i,m)$ is ${\cal C}^1$ on $\Theta^\circ \times \overset{\circ}{\Delta}_N$, and the maps $m\mapsto P_t(\{x_j\}\mid x_i,m,a)$, $m\mapsto r_t(x_i,m,a)$ and $m\mapsto g(x_i,m)$ are $\mathcal{C}^1$ on $\overset{\circ}{\Delta}_N$. These maps are continuous on their full domains $\Theta^\circ \times \Delta_N$ and $\Delta_N$, respectively, and their first derivatives extend continuously from the interior to these domains.                                                                                  

        \item [(2)]  The functions $P_t$, $r_t$, $g$ and their first derivatives are bounded and Lipschitz in $m$, uniformly in $(t,i,j,a) \in \llbracket 0, T-1 \rrbracket \times \llbracket 1, N \rrbracket \times \llbracket 1, N \rrbracket \times {\cal A}$.

        \item [(3)]   
    The function $p_t^\theta$, its first derivatives in $(\theta,m)$, and the Lipschitz constants in $m$ of these derivatives are bounded by a measurable map $\ell : {\cal A}\to[0,\infty)$, uniformly in $(t,i,\theta) \in \llbracket 0, T-1 \rrbracket \times \llbracket 1, N \rrbracket \times  \Theta^\circ,m \in \Delta_N$, for some $\ell\in L^1(\nu_A)$.

       \item [(4)] 
    The initial law $\mu_0$ is independent of $\theta$.
    \end{enumerate}

Starting from the constant map $\theta \mapsto \mu_0$, the population recursion defined in~\ref{eq:population-recursion} as $\mu_{t+1}^\theta(j) = \sum_{i=1}^N \mu_t^\theta(i) K_t^\theta(j\mid i,\mu_t^\theta)$ and Assumption~\ref{assumption:discrete-gradient-regularity} give ${\cal C}^1$ maps $\mu_t : \Theta^\circ \to \Delta_N$ by induction for any $t \in \llbracket 1, T \rrbracket$.                                                  
    Differentiating this finite sum by the product and chain rules gives
    \begin{align}
        \nabla_\theta\mu_{t+1}^\theta(j) = \sum_{i=1}^N K_t^\theta(j\mid i,\mu_t^\theta) \nabla_\theta\mu_t^\theta(i) + \sum_{i=1}^N\mu_t^\theta(i) \Big[\nabla_\theta K_t^\theta(j\mid i,\mu_t^\theta)+(D_t^\theta)^\top
      \nabla_m K_t^\theta(j\mid i,\mu_t^\theta) \Big]
      \label{eq:discrete-exact-sensitivity-recursion}
    \end{align}
    Here the last term is the chain rule through $\mu_t^\theta$, whose first $N-1$ coordinates have derivative $D_t^\theta$.

    Since $\mu_t^\theta(N) = 1-\sum_{i<N} \mu_t^\theta(i)$, and by Cauchy--Schwarz
    \begin{align}
        \sum_{i=1}^N\|\nabla_\theta\mu_t^\theta(i)\|
        \leq 2\sum_{i<N}\|\nabla_\theta\mu_t^\theta(i)\|
        \leq 2\sqrt{N-1}\,\|D_t^\theta\|_{\mathrm F},
    \end{align}
    where we recall that $\|D_t^\theta\|_\mathrm{F}^2 = \sum_{i=1}^{N-1} \|\nabla_\theta \mu_t^\theta(i)\|^2$. The derivatives of $K_t^\theta$ are uniformly bounded by Assumption~\ref{assumption:discrete-gradient-regularity}, and $\sum_i\mu_t^\theta(i)=1$. Thus, summing \eqref{eq:discrete-exact-sensitivity-recursion} over $j<N$ gives $\|D_{t+1}^\theta\|_{\mathrm F} \leq C_{N,T}\bigl(1+\|D_t^\theta\|_{\mathrm F}\bigr)$.
    Because $\mu_0$ does not depend on $\theta$, $D_0^\theta=0$. Induction over the finite horizon therefore yields
    \begin{align}
        \sup_{\theta\in\Theta}\max_{t\in{\cal T}} \|D_t^\theta\|_{\mathrm F}\leq C_{N,T}.
        \label{eq:discrete-exact-sensitivity-bound}
    \end{align}

    We next record the regularity of $F_N$. Recall from~\eqref{eq:discrete-prescribed-flow-objective} that
    \begin{align}
        F_N(\theta,z)=\sum_{t=0}^{T-1}\sum_{i=1}^N v_t^\theta(z)(i)\,R_t^\theta(i,m_t)+\sum_{i=1}^N v_T^\theta(z)(i)\,g(i,m_T),
    \end{align}
    where $m_t$ is affine in $z_t$, with constant Jacobian $A_N\in\mathbb{R}^{N\times(N-1)}$. By the product and chain rules,
    \begin{align}
        \nabla_\theta F_N(\theta,z)&=\sum_{t=0}^{T-1}\sum_{i}\Big(\nabla_\theta v_t^\theta(z)(i)\,R_t^\theta(i,m_t)+v_t^\theta(z)(i)\,\nabla_\theta R_t^\theta(i,m_t)\Big)+\sum_{i}\nabla_\theta v_T^\theta(z)(i)\,g(i,m_T),\\
        \nabla_{z_t} F_N(\theta,z)&=\sum_{s=0}^{T-1}\sum_{i}\nabla_{z_t}v_s^\theta(z)(i)\,R_s^\theta(i,m_s)+\sum_{i}\nabla_{z_t} v_T^\theta(z)(i)\,g(i,m_T)+\sum_{i}v_t^\theta(z)(i) \nabla_m\widetilde R_t(i,m_t), 
    \end{align}

    for $t\in\llbracket1,T\rrbracket$, where $\widetilde R_t=R_t^\theta$ for $t<T$ and $\widetilde R_T=g$. By Assumption~\ref{assumption:discrete-gradient-regularity} and dominated convergence, $K_t^\theta$, $R_t^\theta$, $g$ and their first derivatives in $(\theta,m)$ are bounded and Lipschitz in $m$, uniformly in $\theta$. Differentiating the recursion $v_{t+1}^\theta(z)=v_t^\theta(z)K_t^\theta(\cdot\mid\cdot,m_t)$ expresses $\nabla_\theta v_{t+1}^\theta$ and $\nabla_zv_{t+1}^\theta$ through $v_t^\theta$, $\nabla v_t^\theta$, $K_t^\theta$ and its derivatives. Since $v_t^\theta(z)\in\Delta_N$ and $v_0^\theta=\mu_0$ does not depend on $(\theta,z)$, induction over the finite horizon shows that $v_t^\theta$, $\nabla_\theta v_t^\theta$ and $\nabla_zv_t^\theta$ are bounded and Lipschitz in $z$, uniformly in $\theta$. Each term in the two gradients above is a product of such factors, which gives, uniformly in $\theta$ and in probability flows $z,z'$,
    \begin{align}
        \|\nabla_\theta F_N(\theta,z)\| + \|\nabla_z F_N(\theta,z)\|&\leq C_{N,T},\\
        \|\nabla_\theta F_N(\theta,z)-\nabla_\theta F_N(\theta,z')\| +\|\nabla_z F_N(\theta,z)-\nabla_z F_N(\theta,z')\| &\leq C_{N,T}\|z-z'\|.
        \label{eq:discrete-objective-derivative-bounds}
    \end{align}


    We use the Euclidean norm $\|z-z'\|^2 \coloneqq \sum_{t=0}^T \sum_{k=1}^{N-1} |z_t(k) - z'_t(k)|^2$.
    Under this identification, $D^\theta = \nabla_\theta z^\theta \in \mathbb{R}^{(T+1)(N-1)\times d_\theta}$ is the Jacobian of the coordinate flow.

    For each realization of $q$, set $z^{\lambda,\theta}=(1-\lambda)z^\theta+\lambda q$. Since each $q_t$ and $\mu_t^\theta$ is a probability vector,
    \begin{align}
        \|z^{\lambda,\theta}-z^\theta\|\leq C_{N,T}\lambda,\qquad
        \nabla_\theta z^{\lambda,\theta}=(1-\lambda)D^\theta.
        \label{eq:discrete-perturbed-flow-bounds}
    \end{align}
    The chain rule for $J(\theta) = F_N(\theta,z^\theta)$ gives
    \begin{align}
        \label{eq:discrete-gradient-identity}
        \nabla_\theta J(\theta) =  \nabla_\theta F_N(\theta,z^\theta) + (D^\theta)^\top \nabla_z F_N(\theta,z^\theta).
    \end{align}
    For the perturbed composition the same rule gives the integrand $\nabla_\theta F_N(\theta,z^{\lambda,\theta}) + (1-\lambda)(D^\theta)^\top \nabla_z F_N(\theta,z^{\lambda,\theta})$.
    The derivatives in this expression are uniformly bounded by \eqref{eq:discrete-exact-sensitivity-bound} and \eqref{eq:discrete-objective-derivative-bounds}. Thus they provide an integrable bound independent of $q$. Differentiation under the expectation defining $J^\lambda$ is justified by dominated convergence, and hence
    \begin{align}
        \nabla_\theta J^\lambda(\theta) = \mathbb{E}\Big[\nabla_\theta F_N(\theta,z^{\lambda,\theta}) + (1-\lambda)(D^\theta)^\top \nabla_z F_N(\theta, z^{\lambda,\theta}) \Big].
        \label{eq:discrete-perturbed-gradient-identity}
    \end{align}
    Subtracting these identities, and adding and subtracting $(1-\lambda)(D^\theta)^\top\nabla_zF_N(\theta,z^\theta)$, yields
    \begin{align}
        \nabla_\theta J^\lambda(\theta)-\nabla_\theta J(\theta) &= \mathbb{E}\Big[\nabla_\theta F_N(\theta, z^{\lambda,\theta}) - \nabla_\theta F_N(\theta,z^\theta)\\ &\quad+ (1-\lambda)(D^\theta)^\top \big(\nabla_z F_N(\theta,z^{\lambda,\theta}) - \nabla_z F_N(\theta,z^\theta) \big) - \lambda(D^\theta)^\top\nabla_z F_N(\theta,z^\theta) \Big].
    \end{align}
    Applying \eqref{eq:discrete-exact-sensitivity-bound}, \eqref{eq:discrete-objective-derivative-bounds}, and \eqref{eq:discrete-perturbed-flow-bounds}, and using $1-\lambda\leq1$, gives
    \begin{align}
        \sup_{\theta\in\Theta} \|\nabla_\theta J^\lambda(\theta)-\nabla_\theta J(\theta)\| \leq C_T^\nabla\lambda,\qquad C_T^\nabla\coloneqq C_{N,T}.
    \end{align}
    This proves the gradient estimate.

By the proof of Theorem~\ref{theorem:discrete-perturbation-consistency}, $J$ and $J^\lambda$ are differentiable on $\Theta^\circ\supset\Theta$, hence continuous on the compact set $\Theta$. Maximizers $\theta^\star$ of $J$ and $\theta_\lambda^\star$ of $J^\lambda$ therefore exist, and the objective estimate gives
    \begin{align}
        J(\theta_\lambda^\star)\geq J^\lambda(\theta_\lambda^\star)-C_T\lambda\geq J^\lambda(\theta^\star)-C_T\lambda\geq J(\theta^\star)-2C_T\lambda.
    \end{align}
    If $\theta_{\lambda_n}^\star\to\bar\theta$ with $\lambda_n\to0$, continuity of $J$ gives $J(\bar\theta)=\lim_nJ(\theta_{\lambda_n}^\star)\geq J(\theta^\star)$, so $\bar\theta$ maximizes $J$.

\label{assumption:randomizer_rho_discrete}
We will assume the following:
\begin{enumerate}
    \item[(1)]
    The random variables $(U_t)_{t\in\llbracket 1,T\rrbracket}$ are
    independent and identically distributed over $\mathbb{R}^{N-1}$, with
    density $\rho$ with respect to the Lebesgue measure, with $\rho\in {\cal C}^1(\mathbb{R}^{N-1};(0,+\infty))$.
    \item[(2)] There exist constants $C_\rho>0$ and $\beta>N$ such that, for every $u\in\mathbb{R}^{N-1}$,
    \begin{align}
        \rho(u)\bigl(1+\|\nabla\log\rho(u)\|_1\bigr)
        \leq C_\rho e^{-\beta\|u\|_1}.
        \label{eq:discrete-rho-decay}
    \end{align}
\end{enumerate}

\label{lemma:discrete-law-M}
For every $z\in{\cal Z}_N$ and $\lambda\in(0,1)$, the random variable $\Psi_\lambda(z,Q_t)$ admits the density $h^\lambda(\cdot\mid z)$ defined in~\eqref{eq:discrete-main-density} with respect to Lebesgue measure in simplex coordinates:
\begin{align}
    h^\lambda(y\mid z)
    =\frac{1}{\lambda^{N-1}}
    f_Q\big(q^\lambda(y\mid z)\big),
    \qquad y\in Y_\lambda(z),
\end{align}
and the density is zero elsewhere. In particular, for every $t\in\llbracket1,T\rrbracket$ and $\theta\in\Theta$, the random variable $M_t^{\lambda,\theta}$ defined in~\eqref{eq:discrete-main-transport} has density $h^\lambda(\cdot\mid z_t^\theta)$ in these coordinates.

Fix $z\in{\cal Z}_N$ and $\lambda\in(0,1)$. The affine map $\Psi_\lambda(z,\cdot)$ defined in~\eqref{eq:discrete-perturbation-map} is a ${\cal C}^1$-diffeomorphism from the simplex interior onto $Y_\lambda(z)$, with inverse $q^\lambda(\cdot\mid z)$ and Jacobian determinant $\lambda^{N-1}$.

Since $Q_t=\varphi(U_t)$ and $U_t$ has density $\rho$, the change-of-variables formula gives
\begin{align}
    f_Q(q) = \frac{\rho(\varphi^{-1}(q))}{\prod_{i=1}^N q_i}.
\end{align}
Applying the change-of-variables formula again gives
\begin{align}
    h^\lambda(y\mid z) =\frac{1}{\lambda^{N-1}}  f_Q\big(q^\lambda(y\mid z)\big),
    \qquad y\in Y_\lambda(z),
\end{align}
with density zero elsewhere. Taking $z=z_t^\theta$ gives the result for $M_t^{\lambda,\theta}$.

\label{lemma:discrete-density-extension}
Under Assumption~\ref{assumption:randomizer_rho_discrete}, identify the simplex with its first $N-1$ coordinates and define
\begin{align}
    \widetilde f_Q:\mathbb{R}^{N-1}\longrightarrow[0,\infty),\qquad
    \widetilde f_Q(q)\coloneqq
    \begin{cases}
        f_Q(q),&q\in{\cal Z}_N^\circ,\\
        0,&q\notin{\cal Z}_N^\circ.
    \end{cases}
\end{align}
Then $\widetilde f_Q\in{\cal C}_c^1(\mathbb{R}^{N-1})$ and both its value and its gradient vanish on $\partial{\cal Z}_N$.

For $q\in{\cal Z}_N^\circ$, set $q_N=1-\sum_{i=1}^{N-1}q_i$, $u=\varphi^{-1}(q)$, $r=\|u\|_1$ and $u_N=0$. Writing $S=\sum_{i=1}^Ne^{u_i}$ gives $q_i=e^{u_i}/S$. If $a=\max_{1\leq i\leq N}u_i\geq0$, then $S\leq Ne^a$, $a-u_i\leq r$ and $Na-\sum_{i=1}^{N-1}u_i\leq(N-1)r$. Hence
\begin{align}
    \max_{1\leq i\leq N}\frac1{q_i}
    &\leq Ne^r,\qquad
    \frac1{\prod_{i=1}^Nq_i} = S^N e^{-\sum_{i=1}^{N-1}u_i}
    \leq N^N e^{(N-1)r}.
\end{align}
Using $f_Q(q)=\rho(u)/\prod_{i=1}^Nq_i$ and the formula for $H_k=\partial_{q_k}\log f_Q$, these bounds give
\begin{align}
    |f_Q(q)|+\|\nabla_q f_Q(q)\|_1
    &\leq C_N e^{Nr}\rho(u)
    \bigl(1+\|\nabla\log\rho(u)\|_1\bigr)\\
    &\leq C_NC_\rho e^{-(\beta-N)r},
\end{align}
where $C_N$ depends only on $N$.

As $q\in{\cal Z}_N^\circ$ approaches any point of $\partial{\cal Z}_N$, we have $\min_{1\leq i\leq N}q_i\to0$. The bound on $\max_{1\leq i\leq N}q_i^{-1}$ therefore gives
\begin{align}
    r=\|\varphi^{-1}(q)\|_1
    \geq\log\frac{1}{N\min_{1\leq i\leq N}q_i}
    \longrightarrow\infty.
\end{align}
Since $\beta>N$, the preceding estimate shows that $f_Q(q)\to0$ and $\nabla_q f_Q(q)\to0$ as $q$ approaches the boundary from the interior. In particular, $\widetilde f_Q$ is continuous at every boundary point.

It remains to prove differentiability there. Define
\begin{align}
    \partial{\cal Z}_N &\coloneqq \bigg\{ z\in{\cal Z}_N : z_k = 0 \text{ for some } k \text{ or } \sum_{k=1}^{N-1} z_k = 1\bigg\},\quad
    {\cal Z}_N^\circ \coloneqq \bigg\{z\in(0,\infty)^{N-1} : \sum_{k=1}^{N-1}z_k < 1\bigg\}.
\end{align}
Fix $\bar q\in\partial{\cal Z}_N$ and let $q\in{\cal Z}_N^\circ$. The segment from $\bar q$ to $q$ lies in the interior except at $\bar q$. Applying the one-dimensional mean value theorem along this segment gives a point $\xi_q$ on its open part such that
\begin{align}
    \widetilde f_Q(q)-\widetilde f_Q(\bar q)
    =\nabla_q f_Q(\xi_q)\cdot(q-\bar q).
\end{align}
Since $\xi_q$ lies between $\bar q$ and $q$, $\|\xi_q-\bar q\|\leq\|q-\bar q\|$. Thus $\xi_q\to\bar q$ as $q\to\bar q$, and the boundary limit of the interior gradient gives $\nabla_q f_Q(\xi_q)\to0$. By the Cauchy--Schwarz inequality,
\begin{align}
    \frac{|\widetilde f_Q(q)-\widetilde f_Q(\bar q)|}
    {\|q-\bar q\|}
    \leq\|\nabla_q f_Q(\xi_q)\|\longrightarrow0.
\end{align}
For $q\notin{\cal Z}_N^\circ$, the numerator is zero by definition. Thus the difference quotient tends to zero from every direction, proving that $\nabla\widetilde f_Q(\bar q)=0$.

The gradient is continuous across the boundary: it tends to zero from the interior and is zero outside. Therefore $\widetilde f_Q\in{\cal C}^1(\mathbb{R}^{N-1})$. Finally, its support is contained in the closed bounded set ${\cal Z}_N$, so $\widetilde f_Q\in{\cal C}_c^1(\mathbb{R}^{N-1})$.

\label{lemma:discrete-stein}
    Suppose Assumption~\ref{assumption:randomizer_rho_discrete} holds and let $Q = \varphi(U)$, with $U\sim\rho$. Let $\kappa\in(0,1)$, $c\in\Delta_N$, and let $h:\Delta_N \to \mathbb{R}$ be continuous, ${\cal C}^1$ on $\overset{\circ}{\Delta}_N$ in the coordinates $(m_1,\ldots,m_{N-1})$, with bounded gradient. Then, for every $k\in\llbracket1,N-1\rrbracket$,
    \begin{align}
        \mathbb{E}\big[h\big((1-\kappa)c+\kappa Q\big)H_k(Q)\big]=-\kappa\,\mathbb{E}\big[\partial_k h\big((1-\kappa)c+\kappa Q\big)\big].
        \label{eq:discrete-stein}
    \end{align}
    In particular, $\mathbb{E}[H(Q)]=0$.

Define $g : \Delta_N\to\mathbb{R}$ by $g(q) \coloneqq h\big((1-\kappa)c+\kappa q\big)$. Since $\kappa> 0$, for $q\in\overset{\circ}{\Delta}_N$ every coordinate of $(1-\kappa) c + \kappa q$ is strictly positive, hence $(1-\kappa)c+\kappa q\in\overset{\circ}{\Delta}_N$, even if $c\in\partial\Delta_N$. Therefore $g$ is continuous on $\Delta_N$, ${\cal C}^1$ on $\overset{\circ}{\Delta}_N$, and
    \begin{align}
        \label{eq:stein-chain-rule}
        \partial_k g(q) = \kappa\,\partial_k h\big((1-\kappa)c+ \kappa q\big)
    \end{align}
    is bounded. Using Lemma~\ref{lemma:discrete-density-extension}, since $H_k = \partial_k \log f_Q$ on $\overset{\circ}{\Delta}_N$, we have $H_k f_Q = \partial_k f_Q = \partial_k \widetilde f_Q$ there, and consequently
    \begin{align}
        \mathbb{E}[g(Q)H_k(Q)] = \int_{\overset{\circ}{\Delta}_N} g(q)\, \partial_k \widetilde f_Q(q)\, \mathrm{d} q,
        \label{eq:stein-start}
    \end{align}
    where the integrand is bounded, because $g$ is continuous on the compact set $\Delta_N$ and $\widetilde f_Q\in{\cal C}_c^1(\mathbb{R}^{N-1})$.

    \emph{Splitting the integral.} Throughout, points of $\overset{\circ}{\Delta}_N$ are written in the coordinates $q=(q_1,\ldots,q_{N-1})$, with $q_N=1-\sum_{i=1}^{N-1}q_i$. Fix $k$ and separate the $k$-th coordinate from the others: write $q_{-k}\coloneqq(q_i)_{i\neq k,\, i\leq N-1}$, and denote by $(s,q_{-k})$ the point whose $k$-th coordinate is $s$ and whose other coordinates are $q_{-k}$. A point $(s,q_{-k})$ lies in $\overset{\circ}{\Delta}_N$ if and only if
    \begin{align}
        q_{-k}\in S_{-k}\coloneqq\Big\{q_{-k}:q_i>0\ \text{for all } i\neq k,\ \sum_{i\neq k}q_i<1\Big\}
        \quad\text{and}\quad
        0<s<b(q_{-k})\coloneqq1-\sum_{i\neq k}q_i.
    \end{align}
    By Fubini's theorem, which applies because the integrand in~\eqref{eq:stein-start} is bounded on a bounded set,
    \begin{align}
        \mathbb{E}[g(Q)H_k(Q)]=\int_{S_{-k}}\bigg(\int_0^{b(q_{-k})}g(s,q_{-k})\,\partial_k\widetilde f_Q(s,q_{-k})\,\mathrm{d} s\bigg)\mathrm{d} q_{-k}.
        \label{eq:stein-fubini}
    \end{align}

    \emph{Integration by parts in one variable.} Fix $q_{-k}\in S_{-k}$ and write $b=b(q_{-k})$. The functions $s\mapsto g(s,q_{-k})$ and $s\mapsto\widetilde f_Q(s,q_{-k})$ are continuous on $[0,b]$ and ${\cal C}^1$ on $(0,b)$, with bounded derivatives. Both endpoints lie on $\partial\Delta_N$: at $s=0$, the $k$-th coordinate is $q_k=0$, and at $s=b$, the last coordinate is $q_N=1-b-\sum_{i\neq k}q_i=0$. A point of $\Delta_N$ with a zero coordinate lies on $\partial\Delta_N$. By Lemma~\ref{lemma:discrete-density-extension}, $\widetilde f_Q=0$ on the simplex boundary, so $\widetilde f_Q(0,q_{-k})=\widetilde f_Q(b,q_{-k})=0$. Integrating by parts on $[0,b]$ therefore gives
    \begin{align}
        \int_0^{b}g(s,q_{-k})\,\partial_k\widetilde f_Q(s,q_{-k})\,\mathrm{d} s
        &=\Big[g(s,q_{-k})\,\widetilde f_Q(s,q_{-k})\Big]_{s=0}^{s=b}-\int_0^{b}\partial_kg(s,q_{-k})\,\widetilde f_Q(s,q_{-k})\,\mathrm{d} s\\
        &=-\int_0^{b}\partial_kg(s,q_{-k})\,\widetilde f_Q(s,q_{-k})\,\mathrm{d} s.
    \end{align}

    \emph{Conclusion.} Substituting this into~\eqref{eq:stein-fubini}, recombining the two integrals by Fubini's theorem, and using $\widetilde f_Q=f_Q$ on $\overset{\circ}{\Delta}_N$ and~\eqref{eq:stein-chain-rule},
    \begin{align}
        \mathbb{E}[g(Q)H_k(Q)]
        = -\int_{\overset{\circ}{\Delta}_N} \partial_k g(q)\, f_Q(q)\,\mathrm{d} q
        = -\kappa\, \mathbb{E}\big[\partial_k h\big((1-\kappa)c+\kappa Q\big)\big].
    \end{align}
    Since $g(Q)=h((1-\kappa)c+\kappa Q)$, this is~\eqref{eq:discrete-stein}. Taking $h$ constant gives $\mathbb{E}[H_k(Q)]=0$ for every $k\in\llbracket1,N-1\rrbracket$, hence $\mathbb{E}[H(Q)]=0$.

Fix $\lambda\in(0,1)$ and write $Q=(Q_1,\ldots,Q_T)$. Recall that the return ${\cal R}_\theta^\lambda$ and the policy score ${\cal S}_{\mathrm{pol}}^{\lambda,\theta}$ are defined in~\eqref{eq:perturbed-objective}, and the population score ${\cal S}_{\mathrm{mf}}^{\lambda,\theta}$ is defined in~\eqref{eq:discrete-main-scores}. Throughout the proof, $\nabla_\theta F_N(\theta,z)$ denotes the derivative with respect to the first argument, with $z$ held fixed.

    Recall that $z_0^{\lambda,\theta} = z_0$ and $z_t^{\lambda,\theta} = (1-\lambda)z_t^\theta + \lambda q_t$ for $t\in\llbracket1,T\rrbracket$,
    where $q_t$ denotes the first $N-1$ coordinates of $Q_t$. Since $D_0^\theta=0$, equation~\eqref{eq:discrete-perturbed-gradient-identity} gives
    \begin{align}
        \label{eq:discrete-pg-proof-target}
        \nabla_\theta J^\lambda(\theta)
        &= \mathbb{E}\big[\nabla_\theta F_N(\theta, z^{\lambda,\theta})\big] + (1-\lambda)\sum_{t=1}^T (D_t^\theta)^\top \mathbb{E}\big[\nabla_{z_t} F_N(\theta,z^{\lambda,\theta})\big].
    \end{align}
    We identify the two terms separately.



    \@startsection{paragraph}{4}{\z@}{1.5ex plus
   0.5ex minus .2ex}{-1em}{\normalsize\bfseries}{Policy-score term.}







    Fix a prescribed coordinate flow $z$ and write $m_t = (z_t,1 - \sum_{k=1}^{N-1} z_t(k))$. For a trajectory $(x,a) = (x_0,\ldots,x_T,a_0,\ldots,a_{T-1})$, set
    \begin{align}
        {\cal R}(x,a;m) \coloneqq \sum_{t=0}^{T-1} r_t(x_t,m_t,a_t) + g(x_T,m_T).
    \end{align}
    The integral representation of the prescribed-flow objective is
    \begin{align}
        F_N(\theta, z) = \int_{{\cal X}^{T+1} \times {\cal A}^T} {\cal R}(x,a;m) \mu_0(\mathrm{d} x_0) \prod_{t=0}^{T-1} \big[p_t^\theta(a_t\mid x_t,m_t) \nu_A(\mathrm{d} a_t) P_t(\mathrm{d} x_{t+1}\mid x_t,m_t,a_t) \big].
    \end{align}
    With $z$ fixed, the return and transition kernels are independent of $\theta$, only the policy densities depend on $\theta$. Assumption~\ref{assumption:discrete-gradient-regularity} justifies differentiation under the integral, giving
    \begin{align}
        \nabla_\theta F_N(\theta,z) &= \int_{{\cal X}^{T+1} \times {\cal A}^T} {\cal R}(x,a;m) \bigg[\sum_{s=0}^{T-1} \nabla_\theta \log p_s^\theta(a_s\mid x_s, m_s)  \bigg] \mu_0(\mathrm{d} x_0) \\
        &\qquad \times \prod_{t=0}^{T-1} \bigg[p_t^\theta(a_t\mid x_t,m_t)\nu_A(\mathrm{d} a_t) P_t(\mathrm{d} x_{t+1}\mid x_t,m_t,a_t) \bigg].
    \end{align}
    We now evaluate this partial derivative at $z = z^{\lambda,\theta}$. Conditionally on $Q$, the product of kernels above is the trajectory law of the perturbed process. Hence
    \begin{align}
        \left. \nabla_\theta F_N(\theta,z) \right|_{z=z^{\lambda,\theta}} = \mathbb{E}\big[{\cal R}_\theta^\lambda{\cal S}_\mathrm{pol}^{\lambda,\theta} \mid Q \big].
    \end{align}
    Taking expectations yields
    \begin{align}
        \mathbb{E}\big[\nabla_\theta F_N(\theta,z^{\lambda,\theta})\big] =\mathbb{E}\big[ {\cal R}_\theta^\lambda{\cal S}_{\mathrm{pol}}^{\lambda,\theta} \big].
    \label{eq:discrete-policy-score-identification}
    \end{align}


    \@startsection{paragraph}{4}{\z@}{1.5ex plus
   0.5ex minus .2ex}{-1em}{\normalsize\bfseries}{Population-score term.}
    Fix $t \in \llbracket1,T\rrbracket$, and condition on $Q_{-t} \coloneqq (Q_s)_{s\neq t}$. For fixed $Q_{-t}$, define $h_t: \Delta_N \to \mathbb{R}$ by 
    \begin{align}
        h_t(m) \coloneqq F_N\big(\theta, z_0^{\lambda,\theta},\ldots,z_{t-1}^{\lambda,\theta}, (m_1,\ldots,m_{N-1}), z_{t+1}^{\lambda,\theta},\ldots,z_T^{\lambda,\theta}\big)
    \end{align}
    Derivatives of $h_t$ are taken in the coordinates $(m_1,\ldots,m_{N-1})$, with $m_N = 1-\sum_{k=1}^{N-1} m_k$. Thus, for every $k \in \llbracket1,N-1\rrbracket$,
    \begin{align}
        h_t \big((1-\lambda)\mu_t^\theta + \lambda Q_t\big) &= F_N(\theta, z^{\lambda,\theta}),\\
        \partial_{m_k} h_t\big((1-\lambda)\mu_t^\theta + \lambda Q_t\big) &= \partial_{z_t(k)} F_N(\theta,z^{\lambda,\theta}).
    \end{align}
    The required regularity follows from Assumption~\ref{assumption:discrete-gradient-regularity} and~\eqref{eq:discrete-objective-derivative-bounds}. Since $Q_t$ is independent of $Q_{-t}$, Lemma~\ref{lemma:discrete-stein}, applied component-wise, gives
    \begin{align}
        \mathbb{E}\big[F_N(\theta,z^{\lambda,\theta}) H(Q_t)\mid Q_{-t}] = -\lambda\mathbb{E}\big[\nabla_{z_t} F_N(\theta,z^{\lambda,\theta}) \mid Q_{-t}\big].
    \end{align}
    Taking expectations,
    \begin{align}
        \label{eq:discrete-stein-objective}
        \mathbb{E}\big[F_N(\theta,z^{\lambda,\theta})H(Q_t)\big] = -\lambda\mathbb{E}\big[\nabla_{z_t} F_N(\theta,z^{\lambda,\theta})\big]. 
    \end{align}

    Moreover, since $H(Q_t)$ is $\sigma(Q)$-measurable,
    \begin{align}
        \mathbb{E}\big[{\cal R}_\theta^\lambda H(Q_t) \big]
        = \mathbb{E}\big[\mathbb{E}[{\cal R}_\theta^\lambda\mid Q]H(Q_t)\big]
        = \mathbb{E}\big[F_N(\theta,z^{\lambda,\theta})H(Q_t)].
    \end{align}
    Combining this with~\eqref{eq:discrete-stein-objective} yields
    \begin{align}
        -\frac{1-\lambda}{\lambda}(D_t^\theta)^\top \mathbb{E}\big[{\cal R}_\theta^\lambda H(Q_t)\big] = (1-\lambda)(D_t^\theta)^\top \mathbb{E}\big[\nabla_{z_t}F_N(\theta,z^{\lambda,\theta})\big].
    \end{align}
    Summing over $t\in\llbracket 1, T \rrbracket$ gives
    \begin{align}
        \label{eq:discrete-population-score-identification}
        \mathbb{E}\big[{\cal R}_\theta^\lambda{\cal S}_\mathrm{mf}^{\lambda,\theta}\big] = (1-\lambda) \sum_{t=1}^T (D_t^\theta)^\top \mathbb{E}\big[\nabla_{z_t} F_N(\theta,z^{\lambda,\theta})\big].
    \end{align}

    Finally, combining \eqref{eq:discrete-policy-score-identification} and \eqref{eq:discrete-population-score-identification} with \eqref{eq:discrete-pg-proof-target} gives $\nabla_\theta J^\lambda(\theta) = \mathbb{E}\big[{\cal R}_\theta^\lambda({\cal S}_\mathrm{pol}^{\lambda,\theta} + {\cal S}_\mathrm{mf}^{\lambda,\theta})\big]$.

\label{assumption:discrete-score-regularity}
    The policy scores and the population score satisfy
    \begin{align}
        \sup_{t,\theta,i,m} \int_{\cal A} \|\nabla_\theta\log p_t^\theta(a\mid x_i,m)\|^2 \pi_t^\theta(\mathrm{d} a\mid x_i,m) &<\infty,\\
        \mathbb{E}\big[\|H(Q_t)\|^2\big] &<\infty.
    \end{align}

Fix $\theta$. Throughout, $C$ may change from line to line and depend on the fixed dimensions, horizon, and regularity bounds, but not on \(\theta,\lambda,\eta,B,M,n\). Write ${\cal Z}_N = \bigg\{u\in[0,1]^{N-1}:\sum_{k=1}^{N-1} u_k \leq 1\bigg\}$.

For $s\in\llbracket1,T\rrbracket$, write
\begin{align}
    z_s^\theta \coloneqq (\mu_s^\theta(1), \ldots,\mu_s^\theta(N-1)),\qquad
    \widehat z_s \coloneqq (\widehat\mu_s^M(1), \ldots,\widehat\mu_s^M(N-1)),
\end{align}
and set $z^\theta = (z_s^\theta)_{s=1}^T$ and $\widehat z = (\widehat z_s)_{s=1}^T$. Here $\widehat \mu_s^M = \frac{1}{M}\sum_{\ell=1}^M \delta_{X_s^\ell}$ is the empirical population law. We use the Euclidean norm for vectors and stacked coordinate flows. In particular, $\|\widehat z-z^\theta\|^2 = \sum_{s=1}^T \sum_{k=1}^{N-1} |\widehat \mu_s^M(k) - \mu_s^\theta(k)|^2$. 
The time-zero population argument remains fixed at $\mu_0$.

\emph{Conditional mean and its stability.}
For deterministic $c = (c_t)_{t=1}^T\in {\cal Z}_N^T$, $D \in \big(\mathbb{R}^{(N-1)\times d_\theta}\big)^T$, and $\kappa\in[0,1)$, set $z^\kappa=(z_0,(1-\kappa)c_1+\kappa q_1, \ldots, (1-\kappa)c_T+\kappa q_T)$,
where $q_s$ consists of the $N-1$ coordinates of $Q_s$. Define
\begin{align}
    \Gamma^\kappa : {\cal Z}_N^T \times \big(\mathbb{R}^{(N-1)\times d_\theta}\big)^T \to \mathbb{R}^{d_\theta},\qquad
    \Gamma^\kappa(c,D) \coloneqq \mathbb{E}\big[\nabla_\theta F_N(\theta,z^\kappa)\big] + (1-\kappa)\sum_{s=1}^T D_s^\top \mathbb{E}\big[\nabla_{z_s} F_N(\theta,z^\kappa)\big].
\end{align}


For $s\in\llbracket1,T\rrbracket$, let $\bar c_s = (c_s,1-\sum_{k=1}^{N-1}c_s(k))$ and set
\begin{align}
    m_0^\kappa=\mu_0,\qquad
    m_s^\kappa = (1-\kappa)\bar c_s + \kappa Q_s.
\end{align}
Define
\begin{align}
    X_0^\kappa \sim \mu_0,\qquad
    \alpha_s^\kappa \sim \pi_s^\theta(\cdot\mid X_s^\kappa,m_s^\kappa),\qquad
    X_{s+1}^\kappa\sim P_s(\cdot\mid X_s^\kappa, m_s^\kappa, \alpha_s^\kappa),\quad
    s\in\llbracket0,T-1\rrbracket.
\end{align}
Its return and policy score are
\begin{align}
    {\cal R}^\kappa \coloneqq \sum_{s=0}^{T-1} r_s(X_s^\kappa,m_s^\kappa,\alpha_s^\kappa) + g(X_T^\kappa,m_T^\kappa),\qquad
    {\cal S}_\mathrm{pol}^\kappa \coloneqq \sum_{s=0}^{T-1} \nabla_\theta \log p_s^\theta(\alpha_s^\kappa\mid X_s^\kappa, m_s^\kappa),
\end{align}
where each policy derivative holds the action, state and population argument fixed.

For $\kappa > 0$, the policy-score identity~\eqref{eq:discrete-policy-score-identification} and the Stein identity~\eqref{eq:discrete-stein-objective} give
\begin{align}
    \mathbb{E}\big[{\cal R}^\kappa{\cal S}_{\mathrm{pol}}^\kappa\big]=\mathbb{E}\big[\nabla_\theta F_N(\theta,z^\kappa)\big],\qquad
        \mathbb{E}\big[{\cal R}^\kappa H(Q_s)\big]=-\kappa\,\mathbb{E}\big[\nabla_{z_s}F_N(\theta,z^\kappa)\big].
\end{align}
Multiplying the second identity by $-\frac{1-\kappa}{\kappa}D_s^\top$ and summing over $s$ shows that
\begin{align}
    \mathbb{E}\bigg[{\cal R}^\kappa\bigg({\cal S}_{\mathrm{pol}}^\kappa-\frac{1-\kappa}{\kappa}\sum_{s=1}^TD_s^\top H(Q_s)\bigg)\bigg]=\Gamma^\kappa(c,D).
\end{align}
Consequently, $\Gamma^\kappa(c,D)$ is the expectation of the score estimator using population coordinates $c$ and sensitivity matrices $D$.

Since $\Gamma^\kappa(c,D)-\Gamma^\kappa(c,D^\theta)=(1-\kappa)\sum_s(D_s-D_s^\theta)^\top\mathbb{E}[\nabla_{z_s}F_N(\theta,z^\kappa)]$, the derivative bounds~\eqref{eq:discrete-objective-derivative-bounds} imply
\begin{align}
    \big\|\Gamma^\kappa(c,D) - \Gamma^\kappa(c,D^\theta)\big\| \leq C\sum_{s=1}^T \big\|D_s - D_s^\theta\|_\mathrm{F}.
\end{align}
Moreover, the time-zero block of $z^\kappa-(z_0,z^\theta)$ vanishes and, for $s\geq1$,
\begin{align}
    z_s^\kappa-z_s^\theta=(1-\kappa)(c_s-z_s^\theta)+\kappa(q_s-z_s^\theta).
\end{align}
Since $q_s,z_s^\theta\in{\cal Z}_N$ have Euclidean norm at most one, $\|q_s-z_s^\theta\|\leq2$, and the triangle inequality gives
\begin{align}
    \|z^\kappa-(z_0,z^\theta)\|\leq\|c-z^\theta\| + 2\kappa\sqrt{T}.
\end{align}
Write $\bar z^\theta = (z_0,z^\theta)$. Using $\Gamma^0(z^\theta, D^\theta) = \nabla_\theta J(\theta)$, we obtain
\begin{align}
    \Gamma^\kappa(c,D^\theta) - \nabla_\theta J(\theta) 
    &= \mathbb{E}\big[\nabla_\theta F_N(\theta,z^\kappa) - \nabla_\theta F_N(\theta,\bar z^\theta) \big] \\
    &\qquad + (1-\kappa)\sum_{s=1}^T (D_s^\theta)^\top \mathbb{E}\big[ \nabla_{z_s}F_N(\theta,z^\kappa) - \nabla_{z_s} F_N(\theta,\bar z^\theta) \big]
    - \kappa\sum_{s=1}^T (D_s^\theta)^\top \nabla_{z_s} F_N(\theta, \bar z^\theta).
\end{align}
The first two terms are controlled by the Lipschitz continuity in $z$ of the derivatives of $F_N$, while the last term is bounded by $C\kappa$. Indeed,~\eqref{eq:discrete-objective-derivative-bounds} and~\eqref{eq:discrete-exact-sensitivity-bound} give
\begin{align}
    \|\Gamma^\kappa(c,D^\theta) - \nabla_\theta J(\theta)\| &\leq C\mathbb{E}\big[ \|z^\kappa - \bar z^\theta \| \big] + C\kappa \\
    &\leq C\big(\|c-z^\theta\| + \kappa\big)
\end{align}
Combining these estimates yields
\begin{align}
    \label{eq:bias-stability}
    \big\|\Gamma^\kappa(c,D) - \nabla_\theta J(\theta)\big\| \leq C\bigg(\kappa + \|c-z^\theta\| + \sum_{s=1}^T \big\|D_s - D_s^\theta\big\|_\mathrm{F}\bigg).
\end{align}








\emph{Population-flow error.}
Let ${\cal F}_t^\mathrm{pop} \coloneqq \sigma\big(X_s^\ell : s\in\llbracket0,t\rrbracket, \ell\in\llbracket1,M\rrbracket\big)$ where $\sigma$ refers to the generated sigma-algebra.
The particles use independent simulation randomness at each time and rollout step. Conditionally on ${\cal F}_t^\mathrm{pop}$, the variables $(X_{t+1}^\ell)_{l \in \llbracket 1, M \rrbracket}$ are therefore independent, with laws $K_t^\theta(\cdot\mid X_t^\ell, \widehat \mu_t^M)$.
Therefore, $\mathbb{E}[\widehat\mu_{t+1}^M\mid{\cal F}_t^{\mathrm{pop}}]=\Phi_t^\theta(\widehat\mu_t^M,\widehat\mu_t^M)$, with $\Phi_t^\theta$ from~\eqref{eq:common-population-maps}. 

For each $j \in \llbracket1,N\rrbracket$,  writing $p_{\ell j}\coloneqq K_t^\theta(\{x_j\}\mid X_t^\ell,\widehat\mu_t^M)$,
\begin{align}
    \widehat\mu_{t+1}^M(j) - \Phi_t^\theta(\widehat \mu_t^M, \widehat \mu_t^M)(j) = \frac1M \sum_{\ell=1}^M \big(\mathbf 1_{\{X_{t+1}^\ell = x_j\} } - p_{\ell j} \big).
\end{align}
Conditionally on ${\cal F}_t^\mathrm{pop}$, the summands are independent and centered, with variances $p_{\ell j}(1-p_{\ell j})$. Since the squared Euclidean norm is the sum of the squared coordinates,
\begin{align}
    \mathbb{E}\big[\|\widehat \mu_{t+1}^M - \Phi_t^\theta(\widehat \mu_t^M, \widehat \mu_t^M)\|^2 \mid {\cal F}_t^\mathrm{pop}\big] = \frac{1}{M^2} \sum_{j=1}^N \sum_{\ell=1}^M p_{\ell j}(1-p_{\ell j}) \leq \frac1{M^2} \sum_{\ell= 1}^M\sum_{j=1}^N p_{\ell j} = \frac1M,
\end{align}
where we used $1-p_{\ell j} \leq 1$ and $\sum_{j=1}^N p_{\ell j} = 1$.














For $m,m' \in \Delta_N$, insert the intermediate law $\Phi_t^\theta(m,m')$ to obtain
\begin{align}
    d_\mathrm{TV}\big(\Phi_t^\theta(m,m), \Phi_t^\theta(m',m')\big)
    &\leq d_\mathrm{TV}\big(\Phi_t^\theta(m,m), \Phi_t^\theta(m,m')\big) + d_\mathrm{TV}\big(\Phi_t^\theta(m,m'),\Phi_t^\theta(m',m')\big)\\
    &\leq \sum_{i=1}^N m(i) d_\mathrm{TV}\big(K_t^\theta(\cdot\mid x_i,m),K_t^\theta(\cdot\mid x_i,m')\big) + d_\mathrm{TV}(m,m')\\
    &\leq (1+L_K) d_\mathrm{TV}(m,m')
\end{align}
The first term uses the Lipschitz bound of Assumption~\ref{assumption:discrete-uniform-regularity} on the kernel rows. For the second term, the population argument is fixed at $m'$, so the total-variation contraction~\eqref{eq:markov-kernel-contraction} applies.

Since $\mu_{t+1}^\theta=\Phi_t^\theta(\mu_t^\theta,\mu_t^\theta)$, write
\begin{align}
    \widehat\mu_{t+1}^M-\mu_{t+1}^\theta
    =\underbrace{\widehat\mu_{t+1}^M-\Phi_t^\theta(\widehat\mu_t^M,\widehat\mu_t^M)}_{\xi_{t+1}}
     +\underbrace{\Phi_t^\theta(\widehat\mu_t^M,\widehat\mu_t^M)-\Phi_t^\theta(\mu_t^\theta,\mu_t^\theta)}_{\zeta_t}.
\end{align}
Since $\mathbb{E}[\xi_{t+1}\mid {\cal F}_t^\mathrm{pop}]=0$ and $\zeta_t$ is ${\cal F}_t^\mathrm{pop}$-measurable,
\begin{align}
    \mathbb{E}\big[ \langle\xi_{t+1},\zeta_t\rangle\big] = \mathbb{E}\big[\langle\mathbb{E}[\xi_{t+1}\mid {\cal F}_t^\mathrm{pop}], \zeta_t\rangle\big]=0.
\end{align}
Moreover, the preceding total-variation estimate gives
\begin{align}
    \|\zeta_t\|
    &\leq \|\zeta_t\|_1= 2 d_\mathrm{TV}\big(\Phi_t^\theta(\widehat\mu_t^M, \widehat\mu_t^M),\Phi_t^\theta(\mu_t^\theta,\mu_t^\theta)\big)\\
    &\leq 2(1+L_K)d_\mathrm{TV}(\widehat\mu_t^M,\mu_t^\theta)= (1+L_K)\|\widehat\mu_t^M-\mu_t^\theta\|_1\\
    &\leq\sqrt N(1+L_K) \|\widehat \mu_t^M - \mu_t^\theta\|,
\end{align}
where the first and second equalities use the total variation definition of \citet{levin2026markov} and the last inequality follows from Cauchy-Schwarz. Consequently,
\begin{align}
     \mathbb{E}\big[\|\widehat\mu_{t+1}^M-\mu_{t+1}^\theta\|^2\big] &= \mathbb{E}\big[ \|\xi_{t+1}\|^2\big] + \mathbb{E}\big[ \|\zeta_t\|^2\big] \\
     &\leq \frac1M + N(1+L_K)^2 \mathbb{E}\big[\|\widehat \mu_t^M - \mu_t^\theta\|^2 \big].
\end{align}
The initial particles are i.i.d. with law $\mu_0$, so the same variance calculation gives $\mathbb{E}[\|\widehat \mu_0^M - \mu_0\|^2] \leq 1/M$. Induction over the finite horizon gives
\begin{align}
    \max_{s\in{\cal T}}
    \mathbb{E}\big[\|\widehat\mu_s^M - \mu_s^\theta\|^2\big] \leq \frac{C}{M}.
\end{align}
Since $\widehat z_s$ and $z_s^\theta$ contain the first $N-1$ coordinates of these probability vectors,
\begin{align}
    \mathbb{E}\big[\|\widehat z-z^\theta\|^2 \big] &\leq \sum_{s=1}^T \mathbb{E}\big[ \|\widehat\mu_s^M-\mu_s^\theta\|^2\big] \leq \frac{C}{M}.
    \label{eq:bias-population-error}
\end{align}




\emph{Sensitivity error.}
Let ${\cal B}_t$ collect the random inputs used to simulate auxiliary batch $t$. These inputs are independent across batches and independent of the population particle system. Set ${\cal F}_{t-1}^\mathrm{off} \coloneqq {\cal F}_T^\mathrm{pop}\vee \sigma({\cal B}_1,\ldots,{\cal B}_{t-1})$. Conditionally on ${\cal F}_{t-1}^\mathrm{off}$, simulate $n$ independent rollouts of length $t$. For rollout $r\in\llbracket1,n\rrbracket$, draw independent randomizers $\overline Q_s^{(t,r)}$, $s\in\llbracket1,t-1\rrbracket$, with the same law as $Q_s$, and set
\begin{align}
    \overline m_0^{(t,r)} =\mu_0,\qquad
    \overline m_s^{(t,r)} = (1-\eta)\widehat \mu_s^M + \eta\overline Q_s^{(t,r)},\quad
    s\in\llbracket1,t-1\rrbracket.
\end{align}
Define
\begin{align}
    \overline X_0^{(t,r)}&\sim\mu_0,\qquad
    \overline\alpha_s^{(t,r)} \sim \pi_s^\theta(\cdot\mid \overline X_s^{(t,r)},\overline m_s^{(t,r)}
    ),\qquad
    \overline X_{s+1}^{(t,r)} \sim P_s(\cdot\mid \overline X_s^{(t,r)},\overline m_s^{(t,r)}, \overline\alpha_s^{(t,r)}),\quad
    s\in\llbracket0,t-1\rrbracket.
\end{align}
Thus $\overline X_t^{(t,r)}$ is the terminal state of rollout $r$ in auxiliary batch $t$. Set $\widehat D_0 = 0$. For $t\in\llbracket1,T\rrbracket$, define $\widehat D_t\in\mathbb{R}^{(N-1)\times d_\theta}$ recursively by its rows of size $d_\theta$:
\begin{align}
    (\widehat D_t)_{k,:} \coloneqq \frac1n \sum_{r=1}^n \mathbf 1_{\{\overline X_t^{(t,r)}=x_k\} } \bigg[ \sum_{s=0}^{t-1} \nabla_\theta \log p_s^\theta \big(\overline \alpha_s^{(t,r)}\mid \overline X_s^{(t,r)}, \overline m_s^{(t,r)} \big) -\frac{1-\eta}{\eta} \sum_{s=1}^{t-1} \widehat D_s^\top H(\overline Q_s^{(t,r)}) \bigg]^\top,\qquad
    k\in\llbracket1,N-1\rrbracket.
\end{align}
The policy derivatives hold the action, state, and population argument fixed. We write $\widehat D=(\widehat D_t)_{t=1}^T$.




For $k\in\llbracket1,N-1\rrbracket$, define $F_{t,k}(\theta,z) \coloneqq v_t^\theta(z)(k)$ for $z\in{\cal Z}_N^{T+1}$, where $v_t^\theta(z)$ is the prescribed-flow state law from~\eqref{eq:discrete-prescribed-flow-objective}. This is the objective with horizon $t$, zero running reward, and terminal reward $x\mapsto \mathbf 1_{\{x=x_k\} }$. It depends only on $z_0,\ldots,z_{t-1}$ and $F_{t,k}(\theta,\bar z^\theta) = \mu_t^\theta(k)$ for $\bar z^\theta = (z_0,z^\theta)$. The same finite recursion used for $F_N$ gives bounded first derivatives of $F_{t,k}$ that are Lipschitz in $z$, uniformly in $\theta$.

Conditionally on ${\cal F}_{t-1}^\mathrm{off}$, the population coordinates and earlier sensitivity estimates are fixed. Applying the conditional-mean identity and \eqref{eq:bias-stability} to $F_{t,k}$, and combining the $N-1$ rows, gives
\begin{align}
    \label{eq:bias-sensitivity-mean}
    \Big\|\mathbb{E}\big[\widehat D_t\mid {\cal F}_{t-1}^\mathrm{off}\big] - D_t^\theta\Big\|_\mathrm{F} \leq C\bigg(\eta + \|\widehat z - z^\theta\| + \sum_{s=1}^{t-1} \|\widehat D_s - D_s^\theta\|_\mathrm{F}\bigg).
\end{align}

For the conditional fluctuation, let $Y_{t,r}$ be the matrix contributed by rollout $r$ in the definition of $\widehat D_t$, so that $\widehat D_t=n^{-1}\sum_{r=1}^nY_{t,r}$. Write the policy scores as $\overline\Psi_s^{(t,r)}$, as defined in~\eqref{eq:algorithm-auxiliary-policy-score}. Since at most one row of $Y_{t,1}$ is nonzero,
\begin{align}
    \|Y_{t,1}\|_\mathrm{F}^2
    &\leq\bigg\|\sum_{s=0}^{t-1}\overline\Psi_s^{(t,1)}-\frac{1-\eta}{\eta}\sum_{s=1}^{t-1}\widehat D_s^\top H(\overline Q_s^{(t,1)})\bigg\|^2\\
    &\leq2\bigg\|\sum_{s=0}^{t-1}\overline\Psi_s^{(t,1)}\bigg\|^2
    +\frac{2(1-\eta)^2}{\eta^2}\bigg\|\sum_{s=1}^{t-1}\widehat D_s^\top H(\overline Q_s^{(t,1)})\bigg\|^2\\
    &\leq2t\sum_{s=0}^{t-1}\|\overline\Psi_s^{(t,1)}\|^2
    +\frac{2(t-1)}{\eta^2}\sum_{s=1}^{t-1}\|\widehat D_s\|_\mathrm{F}^2\|H(\overline Q_s^{(t,1)})\|^2.
\end{align}
The second inequality uses $\|a-b\|^2\leq2\|a\|^2+2\|b\|^2$. The last uses $\|\sum_{j=1}^L v_j\|^2\leq L\sum_{j=1}^L\|v_j\|^2$ for sums of $t$ and $t-1$ terms, respectively, together with $\|D^\top h\|\leq\|D\|_\mathrm{F}\|h\|$ and $(1-\eta)^2\leq1$. Taking conditional expectations gives
\begin{align}
    \mathbb{E}\big[\|Y_{t,1}\|_\mathrm{F}^2\mid{\cal F}_{t-1}^\mathrm{off}\big]
    &\leq 2t\sum_{s=0}^{t-1}\mathbb{E}\big[\|\overline\Psi_s^{(t,1)}\|^2\mid{\cal F}_{t-1}^\mathrm{off}\big]
    +\frac{2(t-1)}{\eta^2}\sum_{s=1}^{t-1}\|\widehat D_s\|_\mathrm{F}^2\mathbb{E}\big[\|H(\overline Q_s^{(t,1)})\|^2\big]\\
    &\leq\frac{C}{\eta^2}\bigg(1+\sum_{s=1}^{t-1}\|\widehat D_s\|_\mathrm{F}^2\bigg).
\end{align}
The last inequality follows from Assumption~\ref{assumption:discrete-score-regularity} and $0<\eta<1$: the policy-score bound is uniform, the earlier $\widehat D_s$ are fixed under the conditioning, and the new randomizers are independent of ${\cal F}_{t-1}^\mathrm{off}$. Since the $Y_{t,r}$ are conditionally i.i.d.,
\begin{align}
    \label{eq:bias-sensitivity-fluctuation}
    \mathbb{E}\bigg[\big\|\widehat D_t - \mathbb{E}\big[\widehat D_t\mid {\cal F}_{t-1}^\mathrm{off} \big] \big\|_\mathrm{F}^2 \Big| {\cal F}_{t-1}^\mathrm{off} \bigg]
    &=\frac1n\mathbb{E}\bigg[\big\|Y_{t,1}-\mathbb{E}[Y_{t,1}\mid{\cal F}_{t-1}^\mathrm{off}]\big\|_\mathrm{F}^2\Big|{\cal F}_{t-1}^\mathrm{off}\bigg]\notag\\
    &\leq\frac1n\mathbb{E}\big[\|Y_{t,1}\|_\mathrm{F}^2\mid{\cal F}_{t-1}^\mathrm{off}\big]\notag\\
    &\leq \frac{C}{n\eta^2} \bigg(1+\sum_{s=1}^{t-1}\|\widehat D_s\|_\mathrm{F}^2\bigg).
\end{align}



Set $e_t\coloneqq\mathbb{E}\big[\|\widehat D_t-D_t^\theta\|_{\mathrm F}^2\big]$, with $e_0=0$. Write $\widehat D_t-D_t^\theta=A_t+B_t$, with the fluctuation $A_t\coloneqq\widehat D_t-\mathbb{E}[\widehat D_t\mid{\cal F}_{t-1}^{\mathrm{off}}]$ and the conditional error $B_t\coloneqq\mathbb{E}[\widehat D_t\mid{\cal F}_{t-1}^{\mathrm{off}}]-D_t^\theta$. Since $B_t$ is ${\cal F}_{t-1}^{\mathrm{off}}$-measurable and $\mathbb{E}[A_t\mid{\cal F}_{t-1}^{\mathrm{off}}]=0$, the cross term vanishes and $e_t=\mathbb{E}\big[\|A_t\|_{\mathrm F}^2\big]+\mathbb{E}\big[\|B_t\|_{\mathrm F}^2\big]$. By $\|a+b\|^2\leq2\|a\|^2+2\|b\|^2$ and~\eqref{eq:discrete-exact-sensitivity-bound},
\begin{align}
    \mathbb{E}\big[\|\widehat D_s\|_{\mathrm F}^2\big]\leq2e_s+2\|D_s^\theta\|_{\mathrm F}^2\leq2e_s+C.
\end{align}
Squaring~\eqref{eq:bias-sensitivity-mean}, taking expectations with~\eqref{eq:bias-population-error}, and taking expectations in~\eqref{eq:bias-sensitivity-fluctuation}, we obtain
\begin{align}
    e_t \leq C\bigg(\eta^2 + \frac{1}{M} + \frac{1}{n\eta^2}\bigg) + C\bigg(1+\frac{1}{n\eta^2}\bigg)\sum_{s=1}^{t-1}e_s.
\end{align}
Since $n\eta^2 \geq 1$, induction yields
\begin{align}
    \label{eq:bias-sensitivity-error}
    \max_{t\in\llbracket1,T\rrbracket} e_t \leq C\bigg(\eta^2 + \frac{1}{M} + \frac{1}{n\eta^2}\bigg),\qquad
    \max_{t\in\llbracket1,T\rrbracket} \mathbb{E}\big[\|\widehat D_t\|_\mathrm{F}^2\big] \leq C.
\end{align}

\emph{Bias and mean-square error of the online estimator.}
The online stage uses new simulation randomness. Define $\widehat G_{B,M,n}^{\lambda,\eta}$ by equation~\eqref{eq:discrete-main-estimator} and set for simplicity $\widehat G \coloneqq \widehat G^{\lambda,\eta}_{B,M,n}$ Conditional on $(\widehat z,\widehat D)$, its $B$ contributions are i.i.d., and $\overline G \coloneqq \mathbb{E}\big[\widehat G\mid \widehat z,\widehat D\big] = \Gamma^\lambda(\widehat z,\widehat D)$. Squaring~\eqref{eq:bias-stability} with $\kappa=\lambda$, taking expectations, and applying~\eqref{eq:bias-population-error} and~\eqref{eq:bias-sensitivity-error} gives
\begin{align}
    \mathbb{E}\big[\|\overline G- \nabla_\theta J(\theta)\|^2\big] \leq C\bigg(\lambda^2 + \eta^2 + \frac{1}{n\eta^2} + \frac{1}{M}\bigg).
\end{align}
Since $\mathbb{E}[\widehat G] = \mathbb{E}[\overline G]$, Jensen's inequality and $\sqrt{a+b}\leq\sqrt a+\sqrt b$ imply
\begin{align}
    \big\|\mathbb{E}[\widehat G] -\nabla_\theta J(\theta)\big\| \leq C\bigg(\lambda + \eta + \frac{1}{\eta\sqrt{n}} + \frac{1}{\sqrt{M}}\bigg).
\end{align}
Finally, write $Y_b\coloneqq\widehat{\cal R}^{(b)}(\widehat{\cal S}_\mathrm{pol}^{(b)}+\widehat{\cal S}_\mathrm{mf}^{(b)})$, so that $\widehat G=\frac1B\sum_{b=1}^B Y_b$. The returns are bounded by $T\overline R+\overline g$ (Assumption~\ref{assumption:discrete-uniform-regularity}). The same sum-of-squares and matrix bounds as above, together with Assumption~\ref{assumption:discrete-score-regularity}, give
\begin{align}
    \mathbb{E}\big[\|\widehat{\cal S}_\mathrm{pol}^{(1)}\|^2\mid\widehat z,\widehat D\big]&\leq C,\\
    \mathbb{E}\big[\|\widehat{\cal S}_\mathrm{mf}^{(1)}\|^2\mid\widehat z,\widehat D\big]
    &\leq\frac{T(1-\lambda)^2}{\lambda^2}\sum_{t=1}^T\|\widehat D_t\|_\mathrm{F}^2\mathbb{E}\big[\|H(Q_t^{(1)})\|^2\big]
    \leq C\lambda^{-2}\sum_{t=1}^T\|\widehat D_t\|_\mathrm{F}^2.
\end{align}
Since the online randomizers are independent of $(\widehat z,\widehat D)$ and the $Y_b$ are conditionally i.i.d.,
\begin{align}
    \mathbb{E}\Big[\|\widehat G - \overline G\|^2 \Big| \widehat z,\widehat D \Big]
    &=\frac1B\mathbb{E}\big[\|Y_1-\mathbb{E}[Y_1\mid\widehat z,\widehat D]\|^2\mid\widehat z,\widehat D\big]\\
    &\leq\frac1B\mathbb{E}\big[\|Y_1\|^2\mid\widehat z,\widehat D\big]\\
    &\leq \frac{C}{B}\bigg(1 + \lambda^{-2}\sum_{t=1}^T \|\widehat D_t\|_\mathrm{F}^2\bigg).
\end{align}

Taking expectations and using~\eqref{eq:bias-sensitivity-error} bounds this term by $C(1+\lambda^{-2})/B$. Since $\widehat G-\overline G$ has conditional mean zero and $\overline G$ is $\sigma(\widehat z,\widehat D)$-measurable, the cross term vanishes and
\begin{align}
    \mathbb{E}\big[\|\widehat G - \nabla_\theta J(\theta)\|^2\big] &= \mathbb{E}\big[\|\widehat G-\overline G\|^2\big] + \mathbb{E}\big[\|\overline G - \nabla_\theta J(\theta)\|^2\big]\\
    &\leq C\bigg(\lambda^2 + \frac{1+\lambda^{-2}}{B} + \eta^2 + \frac{1}{n\eta^2} + \frac{1}{M}\bigg).
\end{align}
This proves the theorem.

\label{assumption:continuous-fitting-error}
The numerical fitting maps are measurable. For the interacting particle laws $\widehat\mu_t^{\theta,L}$ used in the offline stage, the computed coordinates $\widehat z_{K,t}^{\theta,L}\coloneqq\widehat{\cal E}_{K,L}(\widehat\mu_t^{\theta,L})$ satisfy
\begin{align}
    \sup_{\theta\in\Theta}\max_{t\in{\cal T}}\mathbb{E}\big[\|\widehat z_{K,t}^{\theta,L}-z_{K,t}^\theta\|^2\big]\leq a_L^2,
    \qquad a_L\longrightarrow0.
    \label{eq:continuous-fitting-error}
\end{align}

All maps in the definition of $T_{K,t}^{\lambda,\theta}$ in \eqref{eq:transport_map_randomized} are jointly measurable by construction. 
 First, at $\lambda=0$, by construction it is clear that $T_{K,t}^{0,\theta}(\omega,x,u) = x$.

 Fix $\omega \in \Omega$ and let $X\sim\nu_{K,t}^\theta$ and $U\sim{\cal U}([0,1])$ be independent. Set $I=\iota(X,U)$ and $V=v(X,U)$. Let $f : \llbracket 1, K \rrbracket \times \mathbb{R}^d \times [0,1] \to \mathbb{R}$ be a bounded measurable test map. Set $s_k(x)=\sum_{i=1}^kr_i(x)$ and $s_0(x)=0$. On each interval $[s_{k-1}(x),s_k(x)]$, substitute $u=s_{k-1}(x)+r_k(x)v$ to obtain
 \begin{align}
     \int_{\mathbb{R}^d}\int_0^1 f(\iota(x,u),x,v(x,u))\,\mathrm{d} u\,\nu_{K,t}^\theta(\mathrm{d} x)
&=\sum_{k=1}^K\int_{\mathbb{R}^d}\int_0^1 f(k,x,v)r_k(x)\,\mathrm{d} v\,\nu_{K,t}^\theta(\mathrm{d} x).
 \end{align}
 Since $r_k(x)\nu_{K,t}^\theta(\mathrm{d} x)=p_k\phi_k(x)\,\mathrm{d} x$,
 \begin{align}
     \label{eq: joint_law}
{\cal L}(I,X,V)(\mathrm{d} k,\mathrm{d} x,\mathrm{d} v)
=\sum_{i=1}^K r_i(x)\nu_{K,t}^\theta(\mathrm{d} x)\delta_i(\mathrm{d} k)\,\mathrm{d} v
=\sum_{i=1}^K p_i\phi_i(x)\delta_i(\mathrm{d} k)\,\mathrm{d} x\,\mathrm{d} v.
 \end{align}
    It follows directly from \eqref{eq: joint_law} that $\mathbb{P}_{I} = \sum_{k=1}^{K} p_k \delta_{k}$ that the conditional law of $X|I=k$ for any $k \in \llbracket 1, K \rrbracket$ is given by ${\cal L} \big(X|I=k \big)(\mathrm{d} x) =  \phi_k(x) \mathrm{d} x = {\cal N}(m_k,\Sigma_k)(\mathrm{d} x)$ and that $V \sim {\cal U}([0,1])$ while being independent of $(I,X)$. Hence, it follows that for fixed $\omega \in \Omega$ 
    the law of the target index $J:=\jmath^\lambda(\omega,X,U)$ satisfies
    \begin{align}
        \mathbb{P}(J=j|I=i)= (1-\lambda) \mathbf{1}_{j=i} + \lambda q_{j,t}(\omega).
    \end{align}
    Conditionally on $I=i$ and $J=j$, the vector $(\Gamma_{i,K,t}^{\theta})^{-1}(X-m_{i,K,t}^{\theta})$ is standard Gaussian. Consequently, the transported vector has law ${\cal N}(m_{j,K,t}^{\lambda,\theta}(\omega),\Sigma_{j,K,t}^{\lambda,\theta}(\omega))$ under this conditioning. Summing over $i$ gives the weight $(1-\lambda)p_j+\lambda q_{j,t}(\omega)$,  proving the claim.

\label{assumption:continuous-moment-bounds}
There exists a uniform constant $C_K<\infty$  in $(t,\theta,j ) \in {\cal T} \times \Theta \times \llbracket 1, K \rrbracket $ such that the following holds
\begin{align}
\begin{cases}
    \lVert m_{j,K,t}^\theta \rVert^2+ \lVert \Sigma _{j,K,t}^\theta\|_F^2&\leq C_K, \\
    \mathbb{E} \Big[ \underset{j \in \llbracket 1, K \rrbracket}{\text{ max }} (\lVert A_{j,t} \Vert^2 + \lVert B_{j,t} \rVert^2_{F} ) \Big ] &\leq C_K.
\end{cases}
\end{align}

Fix $t,\theta$ and suppress these indices. We use a coupling of the same source and target mixtures; it need not be the symmetric-square-root transport used in Proposition~\ref{prop:continuous-state-transport}. Independently of $R_t$, draw $I$ with weights $p$, a standard Gaussian vector $Z$, and $V\sim{\cal U}([0,1])$. If $V\leq1-\lambda$, set $J=I$; otherwise draw $J$ with weights $Q_t$, using additional independent randomness. Put
\begin{align}
 X&=m_I+\Sigma_I^{1/2}Z,\qquad
 Y=m_J^\lambda+\Sigma_J^{1/2}((1-\lambda)I_d+\lambda B_{J,t})Z.
\end{align}
Conditionally on $R_t$, this couples $\nu_{K,t}^\theta$ with $M_{K,t}^{\lambda,\theta}$. Indeed, $J$ has weights $(1-\lambda)p+\lambda Q_t$, and its conditional component covariance is precisely the one in~\eqref{eq:continuous-perturbation-map}.

On $\{V\leq1-\lambda\}$,
\begin{align}
 Y-X=\lambda(A_{I,t}-m_I)+\lambda\Sigma_I^{1/2}(B_{I,t}-I_d)Z.
\end{align}
The moment bounds and $\|\Sigma_I^{1/2}(B_{I,t}-I_d)\|_{\mathrm F}^2
\leq\|\Sigma_I\|_{\mathrm{op}}\|B_{I,t}-I_d\|_{\mathrm F}^2$ give a conditional mean squared displacement bounded by $C\lambda^2$. Here and below $C$ depends only on the stated moment bounds and the fixed dimension. On $\{V>1-\lambda\}$, those same bounds, using the maximum over components for $A_t,B_t$, give $\mathbb{E}[\|X\|^2+\|Y\|^2\mid V>1-\lambda]\leq C$. Hence
\begin{align}
 \mathbb{E}[{\cal W}_2^2(M_{K,t}^{\lambda,\theta},\nu_{K,t}^\theta)]
 \leq\mathbb{E}[\|Y-X\|^2]\leq C((1-\lambda)\lambda^2+\lambda)\leq C\lambda.
\end{align}
The Wasserstein triangle inequality followed by Minkowski's inequality yields
\begin{align}
 \big(\mathbb{E}[{\cal W}_2^2(M_{K,t}^{\lambda,\theta},\mu_t^\theta)]\big)^{1/2}
 \leq{\cal W}_2(\nu_{K,t}^\theta,\mu_t^\theta)
 +\big(\mathbb{E}[{\cal W}_2^2(M_{K,t}^{\lambda,\theta},\nu_{K,t}^\theta)]\big)^{1/2},
\end{align}
which proves the claim. When $K=1$, the component-switching construction is unnecessary, and the same coupling gives the  bound $\big(\mathbb{E}[{\cal W}_2^2(M_{1,t}^{\lambda,\theta},\nu_{1,t}^\theta)]\big)^{1/2}\leq C\lambda$.

\label{assumption:continuous-objective-regularity}
    We make the following assumptions
    \begin{enumerate}
        \item [(1)] The randomizers $(R_t)_{t \in {\cal T}}$ are independent across time and independent of the simulation randomness
        \item [(2)] The initial law satisfies $\mu_0 \in {\cal P}_2(\mathbb{R}^d)$. Furthermore, for any $t\in{\cal T},\theta\in\Theta$, and $\eta,m\in{\cal P}_2(\mathbb{R}^d)$, the measure $\Phi_t^\theta(\eta,m)$ belongs to ${\cal P}_2(\mathbb{R}^d)$.

        \item [(3)] There exists a positive constant $L$ such that
        \begin{align} \begin{cases}{\cal W}_2\big(\Phi_t^\theta(\eta,m), \Phi_t^\theta(\eta',m') \big) &\leq L\big({\cal W}_2(\eta,\eta') + {\cal W}_2(m,m') \big),\\
        \big|\overline R_t^\theta(\eta,m) - \overline R_t^\theta(\eta',m') \big| &\leq L\left({\cal W}_2(\eta,\eta') + {\cal W}_2(m,m') \right),\\
        \big|\overline g(\eta,m) - \overline g(\eta',m') \big| &\leq L\left({\cal W}_2(\eta,\eta') + {\cal W}_2(m,m') \right).
    \end{cases}
    \end{align}
      uniformly in $\theta,t,\eta,\eta',m,m'$.
    \end{enumerate}

Fix $\theta \in \Theta$, let $\eta_{K,t}^{\lambda,\theta} \coloneqq{\cal L}(X_t^{K,\lambda,\theta})$, and set $e_t :={\cal W}_2(\eta_{K,t}^{\lambda,\theta},\eta_{K,t}^{0,\theta})$. Independence of the current randomizer and state gives
    \begin{align}
    \begin{cases}
       \eta_{K,t+1}^{\lambda,\theta} &= \mathbb{E} \big[ \Phi_t^{\theta}(\eta_{K,t}^{\lambda,\theta}, M_{K,t}^{\lambda,\theta}) \big], \\
       \eta_{K,t+1}^{0,\theta} &= \Phi_t^{\theta}(\eta_{K,t}^{0,\theta}, \nu_{K,t}^{\theta})
    \end{cases}
    \end{align}

    The squared Wasserstein distance is convex under mixtures. To verify this, let $\gamma_\omega$ be an optimal coupling between $\Phi_t^\theta(\eta_{K,t}^{\lambda,\theta}, M_{K,t}^{\lambda,\theta}(\omega))$ and $\eta_{K,t+1}^{0,\theta}$ for a given realization $\omega$. Taking the expectation $\mathbb{E}[\gamma_\omega]$ yields a valid coupling between the expected measure $\eta_{K,t+1}^{\lambda,\theta}$ and the deterministic measure $\eta_{K,t+1}^{0,\theta}$. Because the Wasserstein distance is the infimum over all valid couplings, it is bounded by the cost of this averaged coupling:
    \begin{align}
        {\cal W}_2^2 \big(\eta_{K,t+1}^{\lambda,\theta}, \eta_{K,t+1}^{0,\theta} \big) \leq \mathbb{E} \Big[ {\cal W}_2^2 \big(\Phi_{t}^{\theta}(\eta_{K,t}^{\lambda,\theta},M_{K,t}^{\lambda,\theta}), \Phi_t^{\theta}(\eta_{K,t}^{0,\theta}, \nu_{K,t}^{\theta}) \big) \Big].
    \end{align}
    Using the Lipschitz continuity of $\Phi_t^\theta$ (Assumption~\ref{assumption:continuous-objective-regularity}), this implies:
    \begin{align}
        e_{t+1}^2 \leq L^2 \mathbb{E} \Big[ \big(e_t + {\cal W}_2(M_{K,t}^{\lambda,\theta}, \nu_{K,t}^{\theta}) \big)^2 \Big]. 
    \end{align}
    Taking the square root and applying Minkowski's inequality with $p=2$ separates the terms:
    \begin{align}
        e_{t+1} \leq L \Big( e_t + \big( \mathbb{E}\big[{\cal W}_2^2(M_{K,t}^{\lambda,\theta}, \nu_{K,t}^{\theta})\big] \big)^{1/2} \Big).
    \end{align}
    Setting $\delta \coloneqq C_K\sqrt{\lambda}$, the perturbation estimate from Proposition~\ref{proposition:continuous-perturbation-estimate} gives $e_{t+1} \leq L(e_t + \delta)$. Since $e_0 = 0$, a direct induction yields $e_t \leq \delta\sum_{s=1}^T L^s$ for any $t\geq1$
.   
    Finally, applying the Lipschitz bounds on the rewards $\overline R_t^\theta$ and terminal cost $\overline g$ from Assumption~\ref{assumption:continuous-objective-regularity}, and summing over time, yields:
    \begin{align}
        |J_K^\lambda(\theta)-J_K(\theta)| \leq L \sum_{t=0}^{T} \Big(e_t + \mathbb{E}\big[{\cal W}_2(M_{K,t}^{\lambda,\theta}, \nu_{K,t}^{\theta})\big]\Big) \leq L \sum_{t=0}^{T} (e_t + \delta) \leq C_{K,T}\sqrt\lambda,
    \end{align}
    uniformly in $\theta$, for some constant $C_{K,T} > 0$ depending only on $L, T$, and $C_K$.

For any $\theta \in \Theta$, we have
    \begin{align}
        J(\theta) - J(\theta^{\star}_{K,\lambda}) &= J(\theta) -J_K^{\lambda}(\theta)  + J_K^{\lambda}(\theta) -  J_K^{\lambda}(\theta^{\star}_{K,\lambda}) + J_K^{\lambda}(\theta^{\star}_{K,\lambda} ) - J(\theta^{\star}_{K,\lambda}) \\
        &\leq 2 \underset{\theta \in \Theta}{\text{ sup }} |J(\theta) - J_K^{\lambda}(\theta)|,
    \end{align}
    where we used that $J_K^{\lambda}(\theta) \leq J_K^{\lambda}(\theta^{\star}_{K,\lambda})$. 
    Hence, by taking the supremum over $\theta \in \Theta$, in the left hand-side, it follows that
    \begin{align}
        0 \leq \underset{\theta \in \Theta}{\text{sup } } J(\theta) - J(\theta^{\star}_{K,\lambda}) \leq  2 \big( C_T^{\text{proj}} \varepsilon_K + C_{K,T} \sqrt{\lambda} \big).
    \end{align}

\label{assumption:continuous-gradient-regularity}
    Assume that:
    \begin{enumerate}
        \item [(1)] \emph{Regularity of the fitted flow.} The parameter set $\Theta$ is compact, and $\theta \mapsto z^\theta = ({\cal E}_K(\mu_t^\theta))_{t=1}^T$ extends to a ${\cal C}^1$ map on an open neighborhood $\Theta^\circ$ of $\Theta$, with values in ${\cal Z}_K^T$. The initial law \(\mu_0\) is independent of \(\theta\).

        \item [(2)] \emph{Regularity of the prescribed-flow objective.}  The map $F_K$ is ${\cal C}^1$ on the open set $\Theta^\circ \times \widetilde {\cal Z}_K^T \subset \mathbb{R}^{d_\theta + Tq_K}$. There exist \(L<\infty\) and \(r\geq0\) such that, uniformly in \(\theta\in\Theta^\circ\) and \(z,z'\in\widetilde{\mathcal Z}_K^T\),
        \begin{align}
            \|\nabla F_K(\theta,z)\| &\leq L(1+\|z\|)^r,\\
            \|\nabla F_K(\theta,z) - \nabla F_K(\theta,z')\| &\leq L(1+\|z\|+\|z'\|)^r\|z-z'\|.
        \end{align}
        Here \(\nabla F_K\) contains the derivatives with respect to both \(\theta\) and \(z\).
        \item [(3)] \emph{Randomizer moments.} Assume Assumption~\ref{assumption:continuous-moment-bounds} and condition~(1) of Assumption~\ref{assumption:continuous-objective-regularity}. The randomizers have a common law $\rho$, independent of $\theta$ and $\lambda$. For some $\lambda_0\in(0,1)$, this law satisfies condition~(1) of Assumption~\ref{assumption: randomizer_rho} for every $0<\lambda\leq\lambda_0$. Moreover, for each $t\in\llbracket1,T\rrbracket$,
        \begin{align}
            \mathbb{E}\Big[\max_{1\leq j\leq K} \big(\|A_{j,t}\|^{r+1} + \|B_{j,t}\|_\mathrm{F}^{2(r+1)}\big) \Big] < \infty.
        \end{align}
    \end{enumerate}

By compactness and the \({\cal C}^1\) regularity of the fitted flow, its coordinates and first derivatives are uniformly bounded. Moreover, because its covariance matrices are positive definite, there exists \(c_K>0\) such that $\Sigma_{j,K,t}^\theta \succeq c_K I_d$ uniformly in $\theta,t,j$. These bounds also hold on a sufficiently small neighborhood of $\Theta$.

    Set 
    \begin{align}
        W \coloneqq 1 + \sum_{t=1}^T \sum_{j=1}^K \big(\|A_{j,t}\| + \|B_{j,t}\|_\mathrm{F}^2\big).
    \end{align}
    The moment assumption gives $\mathbb{E}\big[W^{r+1}\big] < \infty$. We first establish
    \begin{align}
        \label{eq:continuous-gradient-bound1}
        \|Z^{\lambda,\theta} - z^\theta \|+ \|\nabla_\theta Z^{\lambda,\theta} - D^\theta\| \leq C\lambda W.
    \end{align}
    For the weights and means, this follows directly from their affine perturbations. For the covariance block $(j,t)$, recall $\Gamma_{j,K,t}^\theta = (\Sigma_{j,K,t}^\theta)^{1/2}$ and set
    \begin{align}
        V_{j,t}^\lambda \coloneqq 2\lambda(B_{j,t}-I_d) + \lambda^2(B_{j,t} - I_d)^2.
    \end{align}
    By~\eqref{eq:continuous-perturbation-map} and $\Sigma_{j,K,t}^\theta=\Gamma_{j,K,t}^\theta I_d\Gamma_{j,K,t}^\theta$,
    \begin{align}
        \Sigma_{j,K,t}^{\lambda,\theta} - \Sigma_{j,K,t}^\theta
        &=\Gamma_{j,K,t}^\theta\Big(\big((1-\lambda)I_d+\lambda B_{j,t}\big)^2-I_d\Big)\Gamma_{j,K,t}^\theta\\
        &=\Gamma_{j,K,t}^\theta\Big(2\lambda(B_{j,t}-I_d)+\lambda^2(B_{j,t}-I_d)^2\Big)\Gamma_{j,K,t}^\theta\\
        &=\Gamma_{j,K,t}^\theta V_{j,t}^\lambda\Gamma_{j,K,t}^\theta.
    \end{align}
    Since $\lambda^2\leq\lambda$ and $\|(B_{j,t}-I_d)^2\|_\mathrm{F}\leq\|B_{j,t}-I_d\|_\mathrm{F}^2$,
    \begin{align}
        \|V_{j,t}^\lambda\|_\mathrm{F} \leq C\lambda(1 + \|B_{j,t}\|_\mathrm{F}^2).
    \end{align}
    For each parameter coordinate $\theta_\ell$, differentiating $(\Gamma_{j,K,t}^\theta)^2 = \Sigma_{j,K,t}^\theta$ gives
    \begin{align}
        \Gamma_{j,K,t}^\theta \partial_{\theta_\ell} \Gamma_{j,K,t}^\theta + (\partial_{\theta_\ell}\Gamma_{j,K,t}^\theta)\Gamma_{j,K,t}^\theta = \partial_{\theta_\ell}\Sigma_{j,K,t}^\theta.
    \end{align}
    The covariance lower bound implies
    \begin{align}
        \|\partial_{\theta_\ell}\Gamma_{j,K,t}^\theta\|_\mathrm{F} \leq \frac{1}{2\sqrt{c_K}} \|\partial_{\theta_\ell}\Sigma_{j,K,t}^\theta\|_\mathrm{F}.
    \end{align}
    Consequently, both \(\Gamma_{j,K,t}^\theta\) and its first derivatives are uniformly bounded. Since $B_{j,t}$, and hence $V_{j,t}^\lambda$, does not depend on $\theta$, the product rule gives
    \begin{align}
        \partial_{\theta_\ell}\Sigma_{j,K,t}^{\lambda,\theta} - \partial_{\theta_\ell}\Sigma_{j,K,t}^\theta
        = (\partial_{\theta_\ell}\Gamma_{j,K,t}^\theta)V_{j,t}^\lambda\Gamma_{j,K,t}^\theta + \Gamma_{j,K,t}^\theta V_{j,t}^\lambda(\partial_{\theta_\ell}\Gamma_{j,K,t}^\theta),
    \end{align}
    so that, using $\|XYX'\|_\mathrm{F}\leq\|X\|_\mathrm{F}\|Y\|_\mathrm{F}\|X'\|_\mathrm{F}$,
    \begin{align}
        \|\partial_{\theta_\ell}\Sigma_{j,K,t}^{\lambda,\theta} - \partial_{\theta_\ell}\Sigma_{j,K,t}^\theta\|_\mathrm{F}
        \leq 2\|\partial_{\theta_\ell}\Gamma_{j,K,t}^\theta\|_\mathrm{F}\|\Gamma_{j,K,t}^\theta\|_\mathrm{F}\|V_{j,t}^\lambda\|_\mathrm{F}.
    \end{align}
    Together with $\|\Sigma_{j,K,t}^{\lambda,\theta} - \Sigma_{j,K,t}^\theta\|_\mathrm{F}\leq\|\Gamma_{j,K,t}^\theta\|_\mathrm{F}^2\|V_{j,t}^\lambda\|_\mathrm{F}$ and the bound on $V_{j,t}^\lambda$, this yields
    \begin{align}
        \|\Sigma_{j,K,t}^{\lambda,\theta} - \Sigma_{j,K,t}^\theta\|_\mathrm{F} + \|\nabla_\theta \Sigma_{j,K,t}^{\lambda,\theta} - \nabla_\theta \Sigma_{j,K,t}^\theta\|\leq C\lambda(1+  \|B_{j,t}\|_\mathrm{F}^2).
    \end{align}
    Summing over the finitely many blocks proves~\eqref{eq:continuous-gradient-bound1}.

    In particular,
    \begin{align}
        \|Z^{\lambda,\theta}\| + \|\nabla_\theta Z^{\lambda,\theta}\| \leq CW.
    \end{align}
    By the chain rule and the growth assumption in Assumption~\ref{assumption:continuous-gradient-regularity}(2), using $W\geq1$,
    \begin{align}
        \big\|\nabla_\theta\big[F_K(\theta,Z^{\lambda,\theta})\big]\big\|
        &= \big\|\nabla_\theta F_K(\theta,Z^{\lambda,\theta}) + (\nabla_\theta Z^{\lambda,\theta})^\top \nabla_z F_K(\theta,Z^{\lambda,\theta})\big\|\\
        &\leq \big(1+\|\nabla_\theta Z^{\lambda,\theta}\|\big)\,L\big(1+\|Z^{\lambda,\theta}\|\big)^r
        \leq L(1+CW)^{r+1}\leq CW^{r+1},
    \end{align}
    which is integrable. This bound is uniform in $\theta$ in a neighborhood of $\Theta$. By the mean value theorem, the difference quotients of $\theta\mapsto F_K(\theta,Z^{\lambda,\theta})$ are therefore also dominated by $CW^{r+1}$. Dominated convergence then justifies differentiation under the expectation, giving
    \begin{align}
        \nabla_\theta J_K^\lambda(\theta) &= \mathbb{E}\big[\nabla_\theta F_K(\theta,Z^{\lambda,\theta}) + (\nabla_\theta Z^{\lambda,\theta})^\top \nabla_z F_K(\theta,Z^{\lambda,\theta})\big],\\
        \nabla_\theta J_K(\theta) &= \nabla_\theta F_K(\theta,z^\theta) + (D^\theta)^\top \nabla_z F_K(\theta,z^\theta).
    \end{align}
    Subtracting and adding $(D^\theta)^\top \mathbb{E}\big[\nabla_zF_K(\theta,Z^{\lambda,\theta})\big]$ gives
    \begin{align}
        \nabla_\theta J_K^\lambda - \nabla_\theta J_K &= \mathbb{E}\big[\nabla_\theta F_K(\theta,Z^{\lambda,\theta}) - \nabla_\theta F_K(\theta,z^\theta)\big] + (D^\theta)^\top\mathbb{E}\big[\nabla_z F_K(\theta,Z^{\lambda,\theta}) - \nabla_z F_K(\theta,z^\theta) \big]\\
        &\quad + \mathbb{E}\big[(\nabla_\theta Z^{\lambda,\theta} - D^\theta)^\top \nabla_z F_K(\theta,Z^{\lambda,\theta}) \big].
    \end{align}
    Using~\eqref{eq:continuous-gradient-bound1}, the derivative bounds, and the uniform bound on $D^\theta$, each term is bounded by $C\lambda \mathbb{E}\big[W^{r+1}\big]$. The estimate is uniform in $\theta$, proving the result.

\label{assumption: randomizer_rho}
Let ${\cal B}_{\lambda} := \big \lbrace B \in \mathbb{S}_{d} : B \succ - \frac{1-\lambda}{\lambda} I_d \big \rbrace $. We make the following assumptions.
\begin{enumerate}
    \item [(1)] $\rho \big( \Delta_K^{\circ} \times (\mathbb{R}^d)^K \times ({\cal B}_{\lambda})^K \big)=1$.
    \item [(2)] $\rho$ admits a density $f_{(Q,A,B)}$ with respect the Lebesgue measure over $\Delta_K^\circ \times (\mathbb{R}^d)^K \times ({\cal B}_{\lambda})^K$. Moreover, we assume the following factorization
    \begin{align}
        f_{(Q,A,B)}(q,a,b) = f_Q(q) f_A(a) f_B(b),
    \end{align}
    for some maps $f_Q,f_A,f_B$
    implying that $(Q_t,A_t,B_t)$ are mutually independent.
    \item [(3)] For $K\geq2$, $Q_t=\varphi(U_t)$, where the density of $U_t$ satisfies Assumption~\ref{assumption:randomizer_rho_discrete} with $N=K$. For $K=1$, set $Q_t=1$.
\end{enumerate}

\label{lemma:covariance-jacobian}
Fix $\Sigma\in\mathbb{S}_{++}^d$ and $\lambda\in(0,1)$. Define $F:{\cal B}_\lambda\to\mathbb{S}_{++}^d$ by
\[
    F(B)\coloneqq\Sigma^{1/2}\big((1-\lambda)I_d+\lambda B\big)^2
    \Sigma^{1/2},
    \qquad B\in{\cal B}_\lambda.
\]
For $B\in{\cal B}_\lambda$, set $C\coloneqq(1-\lambda)I_d+\lambda B$. The differential of $F$ at $B$ is the linear map
\begin{align}
    DF(B):\mathbb{S}^d\to\mathbb{S}^d,\qquad H\mapsto\lambda\Sigma^{1/2}(CH+HC)\Sigma^{1/2}.
\end{align}
Its determinant, computed in the same independent-entry coordinates on the domain and codomain, is
\begin{align}
    \det DF(B) = \lambda^{d(d+1)/2}(\det\Sigma)^{(d+1)/2} \prod_{i=1}^d(2c_i)  \prod_{1\leq i<j\leq d}(c_i+c_j).
\end{align}
where $c_1,\ldots,c_d>0$ are the eigenvalues of $C$.

Set $S\coloneqq\Sigma^{1/2}$. For symmetric $H$ small enough that $B+H\in{\cal B}_\lambda$, expansion gives
    \begin{align}
        F(B+H)-F(B)=\lambda S(CH+HC)S+\lambda^2SH^2S.
    \end{align}
    The last term is $O(\|H\|_\mathrm{F}^2)$, which proves the formula for $DF(B)$. Define the linear maps ${\cal L}_C,{\cal C}:\mathbb{S}^d\to\mathbb{S}^d$ by ${\cal L}_C(H)\coloneqq CH+HC$ and ${\cal C}(H)\coloneqq SHS$. Then
    \begin{align}
        DF(B)(H)=\lambda\,{\cal C}\big({\cal L}_C(H)\big),\qquad
        \det DF(B)=\lambda^{d(d+1)/2}\det{\cal C}\,\det{\cal L}_C,
    \end{align}
    since $\dim\mathbb{S}^d=d(d+1)/2$.
    Let $(u_1,\ldots,u_d)$ be an orthonormal eigenbasis of $C$, with $Cu_i=c_iu_i$, and set $E_{i,j}\coloneqq u_iu_j^\top$. The matrices $E_{i,i}$ and $E_{i,j}+E_{j,i}$, for $i<j$, form a basis of $\mathbb{S}^d$. Since $CE_{i,j}=c_iE_{i,j}$ and $E_{i,j}C=c_jE_{i,j}$,
    \begin{align}
        {\cal L}_C(E_{i,i})=2c_iE_{i,i},\qquad
        {\cal L}_C(E_{i,j}+E_{j,i})=(c_i+c_j)(E_{i,j}+E_{j,i}).
    \end{align}
    Thus ${\cal L}_C$ is diagonal in this basis, and, since the determinant of a linear map does not depend on the basis,
    \begin{align}
        \det{\cal L}_C=\prod_{i=1}^d(2c_i)
        \prod_{1\leq i<j\leq d}(c_i+c_j).
    \end{align}
    For ${\cal C}$, let $a_1,\ldots,a_d>0$ be the eigenvalues of $S$, and define $E_{i,j}$ as above from an orthonormal eigenbasis of $S$. Since $SE_{i,j}S=a_ia_jE_{i,j}$,
    \begin{align}
        {\cal C}(E_{i,i})=a_i^2E_{i,i}, \qquad
        {\cal C}(E_{i,j}+E_{j,i}) =a_ia_j(E_{i,j}+E_{j,i}).
    \end{align}
    Hence
    \begin{align}
        \det{\cal C}=\prod_{i=1}^da_i^2\prod_{1\leq i<j\leq d}a_ia_j=\prod_{i=1}^d a_i^{d+1}=(\det S)^{d+1}=(\det\Sigma)^{(d+1)/2},
    \end{align}
    since each index appears twice in the first product and $d-1$ times in the second. Substituting the two determinants into the composition formula proves the result.

\label{lemma: Law_z_k}
Under the conditions of Lemma~\ref{lemma:continuous-main-density}, fix $z=(p,m,\Sigma)\in\widetilde{\cal Z}_K$ and $\lambda\in(0,1)$. The inverse coordinates are given by~\eqref{eq:continuous-inverse-coordinates}.
For $b\in({\cal B}_\lambda)^K$, let $c_{j,1},\ldots,c_{j,d}$ denote the eigenvalues of $(1-\lambda)I_d+\lambda b_j$. Define the Jacobian map $\mathcal J^\lambda:\widetilde{\cal Z}_K\times({\cal B}_\lambda)^K\to(0,\infty)$ by
\begin{align}
    \mathcal J^\lambda(z,b)
    \coloneqq\lambda^{q_K}\prod_{j=1}^K
    \bigg[(\det\Sigma_j)^{(d+1)/2}
    \prod_{i=1}^d(2c_{j,i})\prod_{1\leq i<\ell\leq d}(c_{j,i}+c_{j,\ell})\bigg].
    \label{eq:continuous-explicit-jacobian}
\end{align}
Then, for $y\in Y_\lambda(z)$,
\begin{align}
    h^\lambda(y\mid z)
    =\frac{f_Q(q^\lambda(y\mid z))f_A(a^\lambda(y\mid z))f_B(b^\lambda(y\mid z))}
    {\mathcal J^\lambda(z,b^\lambda(y\mid z))},
    \label{eq:continuous-explicit-density}
\end{align}
and the density is zero elsewhere. For $K=1$, the factor $f_Q$ and the free weight coordinates are omitted. In particular, $Z_{K,t}^{\lambda,\theta}$ has density $h^\lambda(\cdot\mid z_{K,t}^\theta)$.

\label{assumption:continuous-statistical-regularity}
    Assume Assumptions~\ref{assumption:continuous-moment-bounds},~\ref{assumption:continuous-objective-regularity}, and~\ref{assumption:continuous-gradient-regularity}. Write $z^\theta = (z_{K,t}^\theta)_{t=1}^T \in \mathbb{R}^{T q_K}$ and $D^\theta = \nabla_\theta z^\theta \in \mathbb{R}^{Tq_K \times d_\theta}$. Assume additionally:
    \begin{enumerate}
        \item [(1)] \emph{Regular fitted coordinates.} There exists a compact set ${\cal C}_K \subset \widetilde {\cal Z}_K$ containing all exact and fitted coordinates used below. The fitted coordinates use the same component ordering as the exact coordinates. The map $\theta \mapsto z^\theta$ is ${\cal C}^3$, with uniformly bounded third derivatives on an admissible neighborhood containing all shifted parameters $\theta \pm \eta e_\ell$.

        \item [(2)] \emph{Fitting accuracy.} Assumption~\ref{assumption:continuous-fitting-error} holds uniformly over the base parameters $u=\theta$ and shifted parameters $u=\theta\pm\eta e_\ell$, for $\theta\in\Theta$ and $0<\eta\leq\eta_0$. Writing $\widehat z^{N,u}=(\widehat z_{K,t}^{N,u})_{t=1}^T$, summing~\eqref{eq:continuous-fitting-error} over time gives $\sup_u\mathbb{E}[\|\widehat z^{N,u}-z^u\|^2]\leq Ca_N^2$. The base fit uses $N=M$ particles and each shifted fit uses $N=n_0$.

        \item [(3)] \emph{Score identities and moments.} The likelihood-ratio identities hold for every prescribed coordinate flow \(c\in\mathcal C_K^T\), both for differentiation in \(\theta\) with \(c\) fixed and for differentiation in \(c\), with no additional boundary term. For one rollout using population arguments $m_0 = \mu_0$ and $m_t = {\cal D}_K(\Psi_\lambda(c_t,R_t))$, denote its return and policy score by ${\cal R}^\lambda(c)$ and ${\cal S}_\mathrm{pol}^\lambda(c)$. Uniformly in $\theta$, $c$ and $0 < \lambda \leq \lambda_0$,
        \begin{align}
            \mathbb{E}\big[ |{\cal R}^\lambda(c)|^2 \|{\cal S}_\mathrm{pol}^\lambda(c)\|^2\big] \leq C,
        \end{align}
        and
        \begin{align}
            \mathbb{E}\Big[|{\cal R}^\lambda (c)|^2 \sum_{t=1}^T \|s^\lambda(\Psi_\lambda(c_t, R_t), c_t)\|^2 \Big] \leq \frac{C}{\lambda^2}.
        \end{align}
        \item [(4)] \emph{Online simulations.} Conditional on the offline estimates, the \(B\) online trajectories are independent and identically distributed, using fresh simulation randomness.
    \end{enumerate}

Fix $\theta$ and set $n_0 \coloneqq n/(2d_\theta)$. For each offline system of $N$ particles simulated under parameter $u$, denote its states by $(X_t^{i,N,u})_{i=1}^N$ and define
    \begin{align}
        \widehat\mu_t^{N,u}\coloneqq\frac1N\sum_{i=1}^N\delta_{X_t^{i,N,u}},\qquad
        \widehat z^{N,u}\coloneqq\big(\widehat{\cal E}_{K,N}(\widehat\mu_t^{N,u})\big)_{t=1}^T\in{\cal C}_K^T.
    \end{align}
    The base system uses $(N,u)=(M,\theta)$, and the shifted systems use $(N,u)=(n_0,\theta\pm\eta e_\ell)$, where $e_\ell$ is the $\ell$-th canonical basis vector of $\mathbb{R}^{d_\theta}$. Set
    \begin{align}
        \widehat z \coloneqq\widehat z^{M,\theta},\qquad
        \widehat D \coloneqq\begin{pmatrix}\widehat D_1\\\vdots\\\widehat D_T\end{pmatrix}\in\mathbb{R}^{Tq_K\times d_\theta},\qquad
        \widehat D e_\ell\coloneqq\frac{\widehat z^{n_0,\theta+\eta e_\ell}-\widehat z^{n_0,\theta-\eta e_\ell}}{2\eta},\quad \ell\in\llbracket1,d_\theta\rrbracket,
    \end{align}
    where $\widehat D_t\in\mathbb{R}^{q_K\times d_\theta}$ is the time-$t$ block, as in~\eqref{eq:continuous-algorithm-sensitivity}. Write $\widehat G\coloneqq\widehat G_{B,M,n}^{\lambda,\eta}(\theta)$. Throughout, the time-zero population argument remains fixed at $\mu_0$.

    \emph{Conditional mean and its stability.} For a prescribed coordinate flow $c$, define the randomized flow by
    \begin{align}
        Z^\lambda : \widetilde {\cal Z}_K^T \times \Omega \longrightarrow \widetilde {\cal Z}_K^T,\qquad
        Z^\lambda(c,\omega) = \big(\Psi_\lambda(c_t, R_t(\omega))\big)_{t=1}^T.
    \end{align}
    We omit $\omega$ for simplicity. Using the prescribed-flow objective $F_K$, define $\Gamma^\lambda : {\cal C}_K^T \times \mathbb{R}^{Tq_K \times d_\theta} \to \mathbb{R}^{d_\theta}$ by
    \begin{align}
        \label{eq:continuous-biasmse-gamma}
        \Gamma^\lambda(c,D) = \mathbb{E}\big[\nabla_\theta F_K(\theta,Z^\lambda(c))\big] + D^\top \mathbb{E}\big[(\nabla_c Z^\lambda(c))^\top \nabla_z F_K(\theta,Z^\lambda(c))\big].
    \end{align}
    Here \(\nabla_c Z^\lambda(c)\) is the Jacobian with respect to the prescribed coordinates.

    The policy-score identity identifies the first term in~\eqref{eq:continuous-biasmse-gamma}. For the population score, differentiation with respect to $c$, followed by the chain rule, gives
    \begin{align}
\mathbb{E}\left[
\mathcal R^\lambda(c)
\begin{pmatrix}
s^\lambda(\Psi_\lambda(c_1,R_1),c_1)\\
\vdots\\
s^\lambda(\Psi_\lambda(c_T,R_T),c_T)
\end{pmatrix}
\right]&=
\nabla_c\mathbb E\!\left[F_K(\theta,Z^\lambda(c))\right]\\
&=
\mathbb E\!\left[
(\nabla_c Z^\lambda(c))^\top
\nabla_zF_K(\theta,Z^\lambda(c))
\right].
\end{align}
    Consequently, $\Gamma^\lambda(c,D)$ is the expectation of the score estimator using coordinates $c$ and sensitivity matrix $D$.

    The same covariance calculation as in the gradient convergence proof gives, uniformly for $c\in{\cal C}_K^T$,
    \begin{align}
        \label{eq:continuous-biasmse-bound}
        \|Z^\lambda(c) - c\| + \|\nabla_cZ^\lambda(c) - I\| \leq C\lambda W,
    \end{align}
    where
    \begin{align}
        W = 1 + \sum_{t=1}^T \sum_{j=1}^K \big(\|A_{j,t}\| + \|B_{j,t}\|_\mathrm{F}^2\big),\qquad
        \mathbb{E}\big[W^{r+1}\big] < \infty.
    \end{align}
    The constant $C$ in~\eqref{eq:continuous-biasmse-bound} depends on $c$ only through an upper bound on $\|c\|$ and a lower bound on the covariance eigenvalues of $c$, and both are uniform over the compact set ${\cal C}_K$. Indeed, $c\mapsto\|c\|$ is continuous, hence bounded on ${\cal C}_K$. Moreover, $\lambda_{\min}(\Sigma)=\min_{\|u\|=1}u^\top\Sigma u$ is $1$-Lipschitz for $\|\cdot\|_\mathrm{op}$, so $c\mapsto\min_j\lambda_{\min}(\Sigma_j)$ is continuous and positive on ${\cal C}_K\subset\widetilde{\cal Z}_K$. It therefore attains a positive minimum $c_K$ on ${\cal C}_K$.

    Since $\|c\|\leq C$ on ${\cal C}_K^T$, $\lambda\leq1$ and $W\geq1$, the bound~\eqref{eq:continuous-biasmse-bound} gives $\|Z^\lambda(c)\|\leq\|c\|+C\lambda W\leq CW$ and $\|\nabla_cZ^\lambda(c)\|\leq\|I\|+C\lambda W\leq CW$. The growth bound in Assumption~\ref{assumption:continuous-gradient-regularity}(2) gives $\|\nabla_zF_K(\theta,Z^\lambda(c))\|\leq L(1+\|Z^\lambda(c)\|)^r\leq CW^r$. Hence
    \begin{align}
        \big\|\mathbb{E}\big[(\nabla_c Z^\lambda(c))^\top \nabla_z F_K(\theta,Z^\lambda(c)) \big] \big\|
        \leq \mathbb{E}\big[\|\nabla_c Z^\lambda(c)\|\,\|\nabla_z F_K(\theta,Z^\lambda(c))\|\big]
        \leq C\,\mathbb{E}\big[W^{r+1}\big]\leq C.
    \end{align}
    Since $\Gamma^\lambda$ is linear in $D$,
    \begin{align}
        \label{eq:continuous-biasmse-gammalambda-bound}
        \big\|\Gamma^\lambda(c,D) - \Gamma^\lambda(c,D^\theta)\big\| \leq C\|D-D^\theta\|_\mathrm{F}.
    \end{align}
    At $\lambda = 0$,
    \begin{align}
        \Gamma^0(c,D^\theta) = \nabla_\theta F_K(\theta,c) + (D^\theta)^\top \nabla_z F_K(\theta,c).
    \end{align}
    Since $Z^0(c)=c$ and $\nabla_cZ^0(c)=I$, subtracting and adding $(D^\theta)^\top\mathbb{E}[\nabla_zF_K(\theta,Z^\lambda(c))]$ gives
    \begin{align}
        \Gamma^\lambda(c,D^\theta) - \Gamma^0(c,D^\theta)
        &= \mathbb{E}\big[\nabla_\theta F_K(\theta,Z^\lambda(c)) - \nabla_\theta F_K(\theta,c)\big]
        + (D^\theta)^\top\mathbb{E}\big[\nabla_z F_K(\theta,Z^\lambda(c)) - \nabla_z F_K(\theta,c)\big]\\
        &\quad + (D^\theta)^\top\mathbb{E}\big[(\nabla_cZ^\lambda(c) - I)^\top\nabla_z F_K(\theta,Z^\lambda(c))\big].
    \end{align}
    By the Lipschitz bound in Assumption~\ref{assumption:continuous-gradient-regularity}(2) and~\eqref{eq:continuous-biasmse-bound}, $\|\nabla F_K(\theta,Z^\lambda(c))-\nabla F_K(\theta,c)\|\leq L(1+\|Z^\lambda(c)\|+\|c\|)^r\|Z^\lambda(c)-c\|\leq C\lambda W^{r+1}$. The last term is bounded by $\|D^\theta\|\,C\lambda W\cdot CW^r$ using~\eqref{eq:continuous-biasmse-bound} and the growth bound. Since $D^\theta$ is uniformly bounded and $\mathbb{E}[W^{r+1}]<\infty$,
    \begin{align}
        \label{eq:continuous-biasmse-gamma-bound}
        \|\Gamma^\lambda(c,D^\theta) - \Gamma^0(c,D^\theta)\|\leq C\lambda.
    \end{align}
    Moreover, the Lipschitz derivative bounds on the compact set of base coordinates give
    \begin{align}
        \label{eq:continuous-biasmse-gammazero-bound}
        \big\|\Gamma^0(c,D^\theta) - \Gamma^0(z^\theta,D^\theta)\big\| \leq C\|c-z^\theta\|.
    \end{align}
    Since $\Gamma^0(z^\theta,D^\theta) = \nabla_\theta J_K(\theta)$, combining~\eqref{eq:continuous-biasmse-gammalambda-bound},~\eqref{eq:continuous-biasmse-gamma-bound}, and~\eqref{eq:continuous-biasmse-gammazero-bound} yields
    \begin{align}
        \label{eq:continuous-biasmse-gamma-gradient-bound}
        \big\|\Gamma^\lambda(c,D) - \nabla_\theta J_K(\theta)\big\| \leq C\big(\lambda + \|c-z^\theta\| + \|D - D^\theta\|_\mathrm{F}\big).
    \end{align}

    \emph{Population-coordinate error.}
    The fitting-accuracy assumption directly gives
    \begin{align}
        \label{eq:continuous-biasmse-z-bound}
        \mathbb{E}\big[\|\widehat z - z^\theta\|^2\big] \leq C a_M^2.
    \end{align}

    \emph{Sensitivity error.}
    Define the exact centered difference $D^\eta \in \mathbb{R}^{Tq_K \times d_\theta}$ column-wise by
    \begin{align}
        D^\eta e_\ell  = \frac{z^{\theta + \eta e_\ell} - z^{\theta-\eta e_\ell}}{2\eta}.
    \end{align}
    Taylor's formula along the $\ell$-th coordinate gives, with Taylor remainder $R_\ell^\pm$,
      \begin{align}
        z^{\theta\pm\eta e_\ell}
        &=z^\theta\pm\eta\,\partial_\ell z^\theta+\frac{\eta^2}{2}\partial_\ell^2z^\theta+R_\ell^\pm,\\
        \|R_\ell^\pm\|
        &\leq\frac{\eta^3}{6}\sup_{|u|\leq\eta}\|\partial_\ell^3z^{\theta+u e_\ell}\|\leq C\eta^3,
    \end{align}
    by Assumption~\ref{assumption:continuous-statistical-regularity}(1). Subtracting the two expansions cancels the constant and quadratic terms. Since $D^\theta e_\ell=\partial_\ell z^\theta$,
    \begin{align}
        \|(D^\eta-D^\theta)e_\ell\|
        =\bigg\|\frac{R_\ell^+-R_\ell^-}{2\eta}\bigg\|\leq C\eta^2.
    \end{align}
    Squaring and summing over the $d_\theta$ columns yields
    \begin{align}
        \label{eq:continuous-biasmse-D-bound}
        \|D^\eta - D^\theta\|_\mathrm{F} \leq C\eta^2.
    \end{align}
    For each shifted fit, set $\epsilon_\ell^\pm\coloneqq\widehat z^{n_0,\theta\pm\eta e_\ell}-z^{\theta\pm\eta e_\ell}\in\mathbb{R}^{Tq_K}$. Subtracting the fitted and exact centered differences gives
    \begin{align}
        (\widehat D-D^\eta)e_\ell
        &=\frac{(\widehat z^{n_0,\theta+\eta e_\ell}-z^{\theta+\eta e_\ell})-(\widehat z^{n_0,\theta-\eta e_\ell}-z^{\theta-\eta e_\ell})}{2\eta}\\
        &=\frac{\epsilon_\ell^+-\epsilon_\ell^-}{2\eta}.
    \end{align}
    The squared Frobenius norm is the sum of the squared column norms. Using $\|a-b\|^2\leq2\|a\|^2+2\|b\|^2$ and the fitting bound $\mathbb{E}[\|\epsilon_\ell^\pm\|^2]\leq Ca_{n_0}^2$ from Assumption~\ref{assumption:continuous-statistical-regularity}(2),
    \begin{align}
        \mathbb{E}\big[\|\widehat D - D^\eta\|_\mathrm{F}^2 \big] = \sum_{\ell=1}^{d_\theta} \mathbb{E}\bigg[\bigg\|\frac{\epsilon_\ell^+ - \epsilon_\ell^-}{2\eta} \bigg\|^2 \bigg] &\leq \frac{1}{2\eta^2} \sum_{\ell=1}^{d_\theta} \big(\mathbb{E}\big[\|\epsilon_\ell^+\|^2\big] + \mathbb{E}\big[\|\epsilon_\ell^-\|^2\big]\big)\\
        &\leq C\frac{a_{n_0}^2}{\eta^2}.
    \end{align}
    Decomposing $\widehat D-D^\theta=(\widehat D-D^\eta)+(D^\eta-D^\theta)$ and using $\|A+B\|_\mathrm{F}^2\leq2\|A\|_\mathrm{F}^2+2\|B\|_\mathrm{F}^2$, together with~\eqref{eq:continuous-biasmse-D-bound}, proves
    \begin{align}
        \label{eq:continuous-biasmse-Dexp-bound}
        \mathbb{E}\big[\|\widehat D -D^\theta\|_\mathrm{F}^2 \big] \leq C\bigg(\eta^4 + \frac{a_{n_0}^2}{\eta^2}\bigg).
    \end{align}
    Because $D^\theta$ is uniformly bounded and $a_{n_0} \leq \eta$,
    \begin{align}
        \mathbb{E}\big[\|\widehat D\|_\mathrm{F}^2\big] \leq C.
    \end{align}

    \emph{Bias and mean-square error.}
    Define the sigma-algebra generated by the offline particle systems by
    \begin{align}
    {\cal F}^\mathrm{off}\coloneqq\sigma\Big(
        \big(X_t^{i,M,\theta}\big)_{
            t\in\llbracket0,T\rrbracket,\,
            i\in\llbracket1,M\rrbracket},
        \big(X_t^{i,n_0,\theta+\varepsilon\eta e_\ell}\big)_{
            t\in\llbracket0,T\rrbracket,\,
            i\in\llbracket1,n_0\rrbracket,\,
            \ell\in\llbracket1,d_\theta\rrbracket,\,
            \varepsilon\in\{-1,1\}}
    \Big).
    \end{align}
    Since the fitted coordinates are functions of these particles, $\widehat z$ and $\widehat D$ are ${\cal F}^\mathrm{off}$-measurable. Set $\overline G\coloneqq\mathbb{E}[\widehat G\mid{\cal F}^\mathrm{off}]$. The online simulation randomness gives $\overline G=\Gamma^\lambda(\widehat z,\widehat D)$. 

    Since $\overline G=\Gamma^\lambda(\widehat z,\widehat D)$, the stability estimate~\eqref{eq:continuous-biasmse-gamma-gradient-bound} and $(a+b+c)^2\leq3(a^2+b^2+c^2)$ give
\begin{align}
    \mathbb{E}\big[\|\overline G-\nabla_\theta J_K(\theta)\|^2\big]
    &\leq C\,\mathbb{E}\big[
        \big(\lambda+\|\widehat z-z^\theta\|
        +\|\widehat D-D^\theta\|_\mathrm{F}\big)^2
    \big]\notag\\
    &\leq C\big(
        \lambda^2
        +\mathbb{E}[\|\widehat z-z^\theta\|^2]
        +\mathbb{E}[\|\widehat D-D^\theta\|_\mathrm{F}^2]
    \big)\notag\\
    &\leq C\bigg(
        \lambda^2+a_M^2+\eta^4
        +\frac{a_{n_0}^2}{\eta^2}
    \bigg),
    \label{eq:continuous-biasmse-overlineg-bound}
\end{align}
where the last inequality uses the population-coordinate bound~\eqref{eq:continuous-biasmse-z-bound} and the sensitivity bound~\eqref{eq:continuous-biasmse-Dexp-bound}.
    Since $\mathbb{E}[\widehat G] = \mathbb{E}[\overline G]$, Jensen’s inequality proves the bias bound in the Theorem.

    Conditional on ${\cal F}^\mathrm{off}$, the online estimator averages $B$ independent contributions. Applying the
same conditional-variance argument as in the paragraph
\emph{Bias and mean-square error of the online estimator} of the discrete state space bias and mean-square error proof in
Appendix~\ref{proof:discrete-bias-mse}, together with the score moment bounds of Assumption~\ref{assumption:continuous-statistical-regularity}(3), gives
    \begin{align}
        \label{eq:continuous-biasmse-widehatg-bound}
        \mathbb{E}\big[\|\widehat G-\overline G\|^2 \mid {\cal F}^\mathrm{off}\big] \leq \frac{C}{B}\big(1+\lambda^{-2}\|\widehat D\|_\mathrm{F}^2\big).
    \end{align}
    Write
$\widehat G-\nabla_\theta J_K(\theta)
=(\widehat G-\overline G)
+(\overline G-\nabla_\theta J_K(\theta))$.
Since $\overline G$ is ${\cal F}^\mathrm{off}$-measurable and
$\mathbb{E}[\widehat G-\overline G\mid{\cal F}^\mathrm{off}]=0$,
the cross term vanishes:
\begin{align}
    \mathbb{E}\big[
        \langle\widehat G-\overline G,\,
        \overline G-\nabla_\theta J_K(\theta)\rangle
    \big]
    &=\mathbb{E}\big[
        \langle
        \mathbb{E}[\widehat G-\overline G\mid{\cal F}^\mathrm{off}],\,
        \overline G-\nabla_\theta J_K(\theta)
        \rangle
    \big]\\
    &=0.
\end{align}
Expanding the squared norm and taking expectations therefore gives
\begin{align}
    \mathbb{E}\big[\|\widehat G-\nabla_\theta J_K(\theta)\|^2\big]
    &=
    \mathbb{E}\big[\|\widehat G-\overline G\|^2\big]
    +\mathbb{E}\big[\|\overline G-\nabla_\theta J_K(\theta)\|^2\big].
\end{align}
    Combining~\eqref{eq:continuous-biasmse-overlineg-bound} and~\eqref{eq:continuous-biasmse-widehatg-bound} proves the result.

\label{assumption : LQ_model}
For any $(t,x,m,a) \in \llbracket 0,T-1\rrbracket\times\mathbb{R}\times{\cal P}_2(\mathbb{R})\times\mathbb{R}$, we assume  
    \begin{align}
    \begin{cases}
    P_t(x,m, a) &= {\cal N}( \beta_t + b_t x + \bar{b}_t \bar{m} + c_t a , d_t), \\
    X_0 &\sim {\cal N}(m_0,\Sigma_0), \\
    \pi_t^{\theta}(\cdot |x,m) &= {\cal N}(e_t^{\theta} x + \bar{e}_t^{\theta}\bar m ,f_t^{\theta})
    \end{cases}
\end{align}
for some $\mathbb{R}$-valued families $(\beta_t)_t,(b_t)_t, (\bar{b}_t)_t, (c_t)_t,(e_t^{\theta})_t, (\bar{e}_t^{\theta})$ and $(d_t)_t, (f_t^{\theta}) \in \mathbb{R}^{+}_{\star}$ and some $m_0 \in \mathbb{R}$ and $\Sigma_0 \in \mathbb{R}_{+}$ and where we denoted  $\bar{m} := \mathbb{E}_{X \sim m}[X]$. 
Moreover, we impose sufficient regularity conditions on the maps \(\theta \mapsto (e_t^{\theta},\bar e_t^{\theta},f_t^{\theta})\) to justify the score-function identity underlying the policy-gradient representation.

\textnormal{(Stability of the process $(X_t)_{t \in {\cal T}}$).}

Let $t \in \llbracket 0, T \rrbracket$ and $\theta \in \Theta$.
Under Assumptions \ref{assumption : LQ_model}, we have 
\begin{align}
    X_{t}^{\theta} \sim  {\cal N} \big(m_t^{\theta}, \Sigma_t^{\theta} \big),
\end{align}
where the sequences $(m_t^{\theta})_{t \in {\cal T}}$ and  $(\Sigma_t^{\theta})_{t \in {\cal T}}$ are solution to the linear system
\begin{align}\label{eq : def_mean_variance_sequence}
\begin{cases}
    m_{t+1}^{\theta} &=  \beta_t + (b_t + \bar{b}_t) m_t^{\theta} + c_t (e_t^{\theta} +\bar{e}_t^{\theta}) m_t^{\theta}, \\ 
    \Sigma_{t+1}^{\theta} &= (b_t + c_t e_t^{\theta})^2 \Sigma_t^{\theta} + c_t^2 (f_t^{\theta}) + d_t 
\end{cases}
\end{align}
starting from $m_0^{\theta} = m_0$ and $\Sigma_0^{\theta} = \Sigma_0$.

The proof is straightforward recalling that $X_{t+1}|(X_t,\mathbb{P}_{X_t}, \alpha_t) \sim P_t(X_t,\mathbb{P}_{X_t},\alpha_t)$ $\mathbb{P}-\text{a.s}$. Hence, it implies that $\mathbb{P}-\text{a.s}$
    \begin{align}\label{eq : identity_LQ}
        X_{t+1} = \beta_t + b_t X_t + \bar{b}_t \mathbb{E}[X_t] + c_t ( e_t^{\theta} X_t + \bar{e}_t^{\theta} \mathbb{E}[X_t] + \sqrt{f_t^{\theta}} \epsilon_{t+1}) + \sqrt{d_t} \tilde{\epsilon}_{t+1},
    \end{align}
    where $\epsilon_{t+1}$ and $\tilde{\epsilon}_{t+1}$ are independent standard Gaussian random variables independent of $X_t$. The result follows taking the expectation and the variance in \eqref{eq : identity_LQ}.

\textnormal{(Transport map representation).}
According to the transport map construction in \ref{prop:continuous-state-transport}, the following holds
\begin{align}
    M_{t}^{\lambda,\theta}(\omega) = {\cal N} \big(m_t^{\lambda,\theta}(\omega) , \Sigma_t^{\lambda,\theta}(\omega) \big), \quad \omega \in \Omega, \quad t \in \llbracket 1, T \rrbracket.
\end{align}
where we set
\begin{align}
\begin{cases}
    m_t^{\lambda,\theta}(\omega) &:=  (1-\lambda) m_t^{\theta} + \lambda A_t(\omega), \\
    \Sigma_t^{\lambda,\theta}(\omega) &:= \big( (1-\lambda)+ \lambda B_t(\omega) \big) ^2 \Sigma_t^{\theta}
\end{cases}
\end{align}

\textnormal{(Law of the random variables $(m_t^{\lambda,\theta}, \Sigma_t^{\lambda,\theta}))_{t \in \llbracket 1, T \rrbracket}$).}\label{lemma : density_randomized}

Let $U_{\lambda} = \mathbb{R} \times  (-\frac{1-\lambda}{\lambda},+ \infty) $. For any $t \in \llbracket 1, T \rrbracket$, $\theta \in \Theta$ and $\lambda  \in (0,1)$, suppose that $(A_t,B_t) \in U_{\lambda} \quad \mathbb{P}-\text{a.s}$ and admits a  strictly positive $\mathcal{C}^1$ density map $f_{(A_t,B_t)}$ with respect to the Lebesgue measure over $U_{\lambda}$. Then  the random variable $\big(m_t^{\lambda,\theta}, \Sigma_t^{\lambda,\theta} \big)$ admits the following density
    \begin{align}
        h^\lambda((m,\Sigma)\mid z_{1,t}^\theta)= \frac{f_{(A_t,B_t)}\big(a_{t}^{\lambda,\theta}(m,\Sigma),b_t^{\lambda,\theta}(m,\Sigma) \big)}{2 \lambda^2 \sigma_t^{\theta} \sqrt{\Sigma}},
    \end{align}
where $z_{1,t}^\theta \coloneqq (m_t^\theta, \Sigma_t^\theta) = (m_t^\theta,(\sigma_t^\theta)^2)\in\mathbb{R}\times\mathbb{R}_+^\star$, and the maps $a_t^{\lambda,\theta}$ and $b_t^{\lambda,\theta}$ are defined as 
\begin{align}
\begin{cases}
    a_t^{\lambda,\theta}(m,\Sigma) &=\frac{ m -(1-\lambda) m_t^{\theta}}{\lambda}, \\
    b_t^{\lambda,\theta}(m,\Sigma) &= \frac{1}{\lambda} \big( \frac{\sqrt{\Sigma}}{\sigma_t^{\theta}}- (1-\lambda) \big)
\end{cases}
\end{align}
and where the quantities $(m_t^{\theta}, \sigma_t^{\theta})$ are given by  \eqref{eq : def_mean_variance_sequence}.

{(Policy gradient in the L-Q setting).}\label{thm : policy_gradient_LQ}

Under the assumptions of Theorem~\ref{theorem:continuous-pg-representation}, for any $\theta\in\Theta$, the map $J^{\lambda}$ defined in \eqref{eq:perturbed-objective} is differentiable with respect to $\theta$ with gradient map given by
\begin{align}\label{eq : policy_gradient_LQ_setting}
    \nabla_{\theta} J^{\lambda}(\theta) &=\mathbb{E} \Big[ \sum_{t=0}^{T-1} R_{t}^{\lambda,\theta} \nabla_{\theta} \text{ log }  \pi_{t}^{\theta}(X_{t}^{\lambda,\theta}, {\cal N}(m_{t}^{\lambda,\theta}, \Sigma_{t}^{\lambda,\theta}), a_{t}^{\lambda,\theta}) +  \sum_{t=1}^{T} R_t^{\lambda,\theta}\nabla_{\theta} \text{ log } h^\lambda((m_t^{\lambda,\theta},\Sigma_t^{\lambda,\theta})\mid z_{1,t}^\theta) \Big] 
\end{align}
where we denoted the random variables $(R_s^{\lambda,\theta})_{s \in {\cal T}}$ as 
\begin{align}
\begin{cases}
    R_t^{\lambda,\theta} &:= \sum_{s=t}^{T-1} r_s \big(X_s^{\lambda,\theta}, {\cal N}(m_s^{\lambda,\theta}, \Sigma_s^{\lambda,\theta}) ,  a_s^{\lambda,\theta} \big) + g(X_T^{\lambda, \theta}, {\cal N}(m_T^{\lambda, \theta}, \Sigma_T^{\lambda, \theta})), \quad t \in \llbracket 0, T-1 \rrbracket   , \\
    R_T^{\lambda,\theta} &:= g \big(X_T^{\lambda,\theta}, {\cal N}( m_{T}^{\lambda,\theta} , \Sigma_T^{\lambda,\theta}) \big)
\end{cases}
\end{align}

{\textnormal{(Score function of the mean-field density).}}\label{corollary: score_mean_field_density}

For any $\lambda \in (0,1)$, $\theta \in \Theta$ and $t \in \llbracket 1, T \rrbracket$, we have
\begin{align}
    \nabla_{\theta} \text{ log } h^\lambda((m,\Sigma)\mid z_{1,t}^\theta) &= - \frac{1-\lambda}{\lambda} \partial_a \text{ log } f_{(A_{t}, B_{t})}(a_{t}^{\lambda,\theta}(m, \Sigma), b_t^{\lambda,\theta}(m, \Sigma)) \nabla_{\theta} m_t^{\theta} \\
    &\quad - {\frac{1}{\lambda}}\partial_b \text{ log } f_{(A_{t}, B_t)}(a_{t}^{\lambda,\theta}(m, \Sigma), b_{t}^{\lambda,\theta}(m, \Sigma)) \frac{\sqrt{\Sigma}}{\sigma_{t}^{\theta}} \nabla_{\theta} \text{ log } \sigma_{t}^{\theta}   \\
    &\quad - \nabla_{\theta} \text{ log }(\sigma_{t}^{\theta}) 
\end{align}

The proof is straightforward noticing that 
    \begin{align}
        \nabla_{\theta} (\frac{1}{\sigma_t^{\theta}}) &= - \frac{\nabla_{\theta} \sigma_t^{\theta}}{(\sigma_t^{\theta})^2} = - \frac{\nabla_{\theta} \text{ log}(\sigma_t^{\theta})}{\sigma_t^{\theta}}
    \end{align}
    and recalling \eqref{lemma : density_randomized}.

\label{prop:transport-simulation-cost}
    One policy update uses
    \begin{align}
        C_{\mathrm{sim}}=
        \begin{cases}
            T(M+B)+nT(T+1)/2,
            &\text{finite states, fresh auxiliary batches},\\
            T(M+n+B),
            &\text{finite states, shared auxiliary batch},\\
            T(M+n+B),
            &\text{continuous states}.
        \end{cases}
        \label{eq:simulator-complexity}
    \end{align}
    These counts exclude the arithmetic cost of mixture fitting and score evaluation. The finite-state MSE theorem covers fresh auxiliary batches; the experiments use a shared batch.
